import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface TimeZoneData {
  zone: string;
  country: string;
  continent: string;
  offset: number; // in minutes
  cities: string[];
}

export interface TransitionStatus {
  zone: string;
  country: string;
  isIn2026: boolean;
  localTime: string;
  timeTo2026: number; // in milliseconds (negative if already in 2026)
}

export interface CelebrationInsight {
  country: string;
  tradition: string;
  greeting: string;
  funFact: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { CelebrationInsight } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getCelebrationInsight = async (country: string): Promise<CelebrationInsight | null> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Provide information about how ${country} celebrates New Year (the transition to 2026). Include a common greeting in their language, one unique tradition, and a fun fact.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            country: { type: Type.STRING },
            tradition: { type: Type.STRING },
            greeting: { type: Type.STRING },
            funFact: { type: Type.STRING },
          },
          required: ["country", "tradition", "greeting", "funFact"]
        },
      },
    });

    if (response.text) {
      return JSON.parse(response.text.trim());
    }
    return null;
  } catch (error) {
    console.error("Error fetching insight from Gemini:", error);
    return null;
  }
};

import React from 'react';
import { TransitionStatus } from '../types';
import { Clock, CheckCircle2, Timer } from 'lucide-react';

interface TimeCardProps {
  status: TransitionStatus;
  onClick: (country: string) => void;
  isSelected: boolean;
}

const formatRemaining = (ms: number) => {
  if (ms <= 0) return "HAPPY 2026!";
  const seconds = Math.floor((ms / 1000) % 60);
  const minutes = Math.floor((ms / (1000 * 60)) % 60);
  const hours = Math.floor((ms / (1000 * 60 * 60)) % 24);
  const days = Math.floor(ms / (1000 * 60 * 60 * 24));

  return `${days}d ${hours}h ${minutes}m ${seconds}s`;
};

const TimeCard: React.FC<TimeCardProps> = ({ status, onClick, isSelected }) => {
  return (
    <div 
      onClick={() => onClick(status.country)}
      className={`relative overflow-hidden cursor-pointer transition-all duration-300 p-5 rounded-2xl border ${
        status.isIn2026 
          ? 'bg-emerald-950/30 border-emerald-500/50 hover:bg-emerald-900/40' 
          : 'bg-slate-900/40 border-slate-700/50 hover:border-blue-500/50'
      } ${isSelected ? 'ring-2 ring-blue-500' : ''}`}
    >
      <div className="flex justify-between items-start mb-4">
        <div>
          <h3 className="text-xl font-bold tracking-tight text-white">{status.country}</h3>
          <p className="text-sm text-slate-400 font-mono">{status.zone}</p>
        </div>
        {status.isIn2026 ? (
          <CheckCircle2 className="text-emerald-400 w-6 h-6 animate-pulse" />
        ) : (
          <Timer className="text-blue-400 w-6 h-6" />
        )}
      </div>

      <div className="space-y-2">
        <div className="flex items-center gap-2 text-slate-300">
          <Clock size={14} />
          <span className="text-sm font-medium">{status.localTime}</span>
        </div>

        <div className="mt-4">
          <p className={`text-xs uppercase tracking-widest font-semibold ${status.isIn2026 ? 'text-emerald-400' : 'text-slate-500'}`}>
            {status.isIn2026 ? 'Current Status' : 'Countdown to 2026'}
          </p>
          <p className={`text-lg font-mono font-bold mt-1 ${status.isIn2026 ? 'text-emerald-300' : 'text-blue-300'}`}>
            {formatRemaining(status.timeTo2026)}
          </p>
        </div>
      </div>

      {/* Background decoration */}
      <div className={`absolute -bottom-6 -right-6 w-24 h-24 rounded-full opacity-10 blur-2xl ${status.isIn2026 ? 'bg-emerald-500' : 'bg-blue-500'}`}></div>
    </div>
  );
};

export default TimeCard;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { TIMEZONES, TARGET_DATE_UTC, TARGET_YEAR } from './constants';
import { TransitionStatus, CelebrationInsight } from './types';
import TimeCard from './components/TimeCard';
import InsightPanel from './components/InsightPanel';
import { getCelebrationInsight } from './services/geminiService';
import { Globe, Timer, Search, LayoutGrid, List, MapPin, Sparkles, ChevronDown } from 'lucide-react';

const App: React.FC = () => {
  const [now, setNow] = useState(new Date());
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [selectedCountry, setSelectedCountry] = useState<string | null>(null);
  const [insight, setInsight] = useState<CelebrationInsight | null>(null);
  const [loadingInsight, setLoadingInsight] = useState(false);
  const [localStatus, setLocalStatus] = useState<TransitionStatus | null>(null);

  // Update real-time clock
  useEffect(() => {
    const interval = setInterval(() => {
      setNow(new Date());
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // Calculate statuses for all tracked zones
  const statuses = useMemo(() => {
    return TIMEZONES.map(tz => {
      // Calculate local time for each zone
      const formatter = new Intl.DateTimeFormat('en-US', {
        timeZone: tz.zone,
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });

      const localTimeStr = formatter.format(now);
      const localDate = new Date(localTimeStr);
      const isIn2026 = localDate.getFullYear() >= TARGET_YEAR;

      // Calculate when 2026 starts in that specific timezone
      // We do this by creating Jan 1, 2026 in that zone and getting its UTC timestamp
      const nextYearDate = new Date('2026-01-01T00:00:00');
      const nextYearInZoneStr = nextYearDate.toLocaleString('en-US', { timeZone: tz.zone });
      const nextYearInZone = new Date(nextYearInZoneStr);

      // Simpler approach for time remaining:
      // Since offset is in minutes, we use the global target minus the offset
      const zoneStartUTC = TARGET_DATE_UTC - (tz.offset * 60 * 1000);
      const timeTo2026 = zoneStartUTC - now.getTime();

      return {
        ...tz,
        isIn2026,
        localTime: localTimeStr,
        timeTo2026
      } as TransitionStatus;
    }).sort((a, b) => b.offset - a.offset); // Order by time of entry (East to West)
  }, [now]);

  // Handle local timezone detection
  useEffect(() => {
    try {
      const userZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
      const formatter = new Intl.DateTimeFormat('en-US', {
        timeZone: userZone,
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });
      const localTimeStr = formatter.format(now);
      const isIn2026 = now.getFullYear() >= TARGET_YEAR;

      // Simplified local remaining
      const startOf2026 = new Date(TARGET_YEAR, 0, 1, 0, 0, 0);
      const timeTo2026 = startOf2026.getTime() - now.getTime();

      setLocalStatus({
        zone: userZone,
        country: 'Your Local Time',
        isIn2026,
        localTime: localTimeStr,
        timeTo2026
      });
    } catch (e) {
      console.warn("Could not determine local timezone");
    }
  }, [now]);

  const handleCountryClick = useCallback(async (country: string) => {
    setSelectedCountry(country);
    setLoadingInsight(true);
    const result = await getCelebrationInsight(country);
    setInsight(result);
    setLoadingInsight(false);
  }, []);

  const filteredStatuses = useMemo(() => {
    return statuses.filter(s => 
      s.country.toLowerCase().includes(searchTerm.toLowerCase()) ||
      s.zone.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [statuses, searchTerm]);

  const stats = useMemo(() => {
    const in2026 = statuses.filter(s => s.isIn2026).length;
    return {
      in2026,
      remaining: statuses.length - in2026,
      next: statuses.find(s => !s.isIn2026)
    };
  }, [statuses]);

  return (
    <div className="min-h-screen bg-black text-slate-100 selection:bg-blue-500/30">
      {/* Navigation / Header */}
      <header className="sticky top-0 z-40 bg-black/50 backdrop-blur-md border-b border-white/5">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center shadow-lg shadow-blue-900/20">
              <Globe className="text-white" size={24} />
            </div>
            <div>
              <h1 className="text-xl font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">
                2026 TRACKER
              </h1>
            </div>
          </div>

          <div className="hidden md:flex items-center gap-6 text-sm font-medium text-slate-400">
            <div className="flex items-center gap-2 px-3 py-1.5 bg-white/5 rounded-full border border-white/5">
              <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
              <span>Live Updates</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-white">{stats.in2026}</span> Countries in 2026
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8">

        {/* Hero Section */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-12">
          {/* Main Global Countdown */}
          <div className="lg:col-span-2 relative overflow-hidden bg-gradient-to-br from-slate-900 to-slate-950 rounded-3xl p-8 border border-white/10 shadow-2xl">
            <div className="relative z-10">
              <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-blue-500/10 text-blue-400 rounded-full border border-blue-500/20 text-xs font-bold uppercase tracking-widest mb-4">
                <Sparkles size={14} />
                Global Transition Phase
              </div>
              <h2 className="text-4xl md:text-6xl font-black text-white mb-2">Countdown to 2026</h2>
              <p className="text-slate-400 max-w-lg mb-8">Tracking the world's journey into the new year. Explore how different cultures celebrate this historic transition.</p>

              <div className="flex flex-wrap gap-8 items-end">
                {localStatus && (
                  <div className="bg-black/40 backdrop-blur p-4 rounded-2xl border border-white/5">
                    <p className="text-xs text-slate-500 uppercase tracking-widest font-bold mb-2 flex items-center gap-2">
                      <MapPin size={12} /> Your Local Time
                    </p>
                    <p className="text-3xl font-mono font-bold text-white">
                      {localStatus.localTime}
                    </p>
                    <p className="text-sm text-blue-400 font-mono mt-1">
                      {localStatus.isIn2026 ? "You are already in 2026!" : `T-minus ${Math.max(0, Math.floor(localStatus.timeTo2026 / 1000 / 60 / 60))} hours`}
                    </p>
                  </div>
                )}

                {stats.next && (
                  <div className="bg-blue-600/10 p-4 rounded-2xl border border-blue-500/20">
                    <p className="text-xs text-blue-400 uppercase tracking-widest font-bold mb-2 flex items-center gap-2">
                      <Timer size={12} /> Next to Transition
                    </p>
                    <p className="text-2xl font-bold text-white">{stats.next.country}</p>
                    <p className="text-sm text-slate-400 font-mono mt-1">
                      In {Math.floor(stats.next.timeTo2026 / 1000 / 60)} minutes
                    </p>
                  </div>
                )}
              </div>
            </div>

            {/* Visual Flair */}
            <div className="absolute top-0 right-0 w-1/2 h-full bg-blue-600/5 blur-[120px] rounded-full"></div>
            <div className="absolute bottom-0 left-0 w-1/3 h-1/2 bg-indigo-600/5 blur-[100px] rounded-full"></div>
          </div>

          {/* Quick Stats Sidebar */}
          <div className="bg-slate-900/50 rounded-3xl p-6 border border-white/5 flex flex-col justify-between">
            <div>
              <h3 className="text-lg font-bold text-white mb-4">Global Status</h3>
              <div className="space-y-4">
                <div className="flex justify-between items-center p-3 bg-white/5 rounded-xl">
                  <span className="text-slate-400 text-sm">Countries in 2026</span>
                  <span className="text-xl font-bold text-emerald-400">{stats.in2026}</span>
                </div>
                <div className="flex justify-between items-center p-3 bg-white/5 rounded-xl">
                  <span className="text-slate-400 text-sm">Remaining Count</span>
                  <span className="text-xl font-bold text-blue-400">{stats.remaining}</span>
                </div>
              </div>
            </div>

            <div className="mt-8">
              <p className="text-xs text-slate-500 mb-4 leading-relaxed">
                As the Earth rotates, the International Date Line dictates the first territories to witness 2026. This tracker updates every second to maintain precision.
              </p>
              <button 
                onClick={() => handleCountryClick(stats.next?.country || 'Kiribati')}
                className="w-full py-3 bg-white text-black font-bold rounded-xl hover:bg-slate-200 transition-colors flex items-center justify-center gap-2"
              >
                Learn New Year Traditions
              </button>
            </div>
          </div>
        </div>

        {/* Filters and Search */}
        <div className="flex flex-col md:flex-row gap-4 mb-8 items-center justify-between">
          <div className="relative w-full md:w-96">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
            <input 
              type="text" 
              placeholder="Search country or timezone..."
              className="w-full bg-slate-900/50 border border-white/10 rounded-2xl py-3 pl-12 pr-4 focus:outline-none focus:ring-2 focus:ring-blue-500/50 text-white"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="flex items-center gap-2 bg-slate-900/50 p-1 rounded-2xl border border-white/10">
            <button 
              onClick={() => setViewMode('grid')}
              className={`p-2 rounded-xl transition-all ${viewMode === 'grid' ? 'bg-white text-black shadow-lg' : 'text-slate-400 hover:text-white'}`}
            >
              <LayoutGrid size={20} />
            </button>
            <button 
              onClick={() => setViewMode('list')}
              className={`p-2 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white text-black shadow-lg' : 'text-slate-400 hover:text-white'}`}
            >
              <List size={20} />
            </button>
          </div>
        </div>

        {/* Timezone Grid */}
        <div className={viewMode === 'grid' 
          ? "grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4" 
          : "space-y-3"
        }>
          {filteredStatuses.map((s) => (
            <TimeCard 
              key={s.zone} 
              status={s} 
              onClick={handleCountryClick}
              isSelected={selectedCountry === s.country}
            />
          ))}
        </div>

        {filteredStatuses.length === 0 && (
          <div className="text-center py-20">
            <div className="w-16 h-16 bg-white/5 rounded-full flex items-center justify-center mx-auto mb-4">
              <Search className="text-slate-500" />
            </div>
            <p className="text-slate-400">No timezones match your search.</p>
          </div>
        )}
      </main>

      {/* AI Insight Panel */}
      <InsightPanel 
        insight={insight} 
        loading={loadingInsight} 
        onClose={() => {
          setInsight(null);
          setSelectedCountry(null);
        }}
      />

      <footer className="mt-20 border-t border-white/5 py-12 px-4 bg-slate-950">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-8">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-white/5 rounded-2xl">
              <Globe className="text-slate-400" size={24} />
            </div>
            <div>
              <p className="text-white font-bold">2026 Global Tracker</p>
              <p className="text-sm text-slate-500">Real-time New Year Observation Tool</p>
            </div>
          </div>
          <div className="text-sm text-slate-600 text-center md:text-right">
            <p>© {new Date().getFullYear()} Global Horizons. Powered by Gemini AI.</p>
            <p className="mt-1">All times are calculated using the International Date Line standard.</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

