import React, { useEffect, useRef } from 'react';

const Fireworks: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = window.innerWidth;
    let height = window.innerHeight;
    let animationId: number;

    const resize = () => {
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = width;
      canvas.height = height;
    };

    window.addEventListener('resize', resize);
    resize();

    // Configuration
    const colors = [
      '#10b981', // Emerald-500
      '#3b82f6', // Blue-500
      '#f59e0b', // Amber-500
      '#ffffff', // White
      '#8b5cf6', // Violet-500
      '#ec4899', // Pink-500
    ];

    class Particle {
      x: number;
      y: number;
      vx: number;
      vy: number;
      alpha: number;
      color: string;
      decay: number;

      constructor(x: number, y: number, color: string) {
        this.x = x;
        this.y = y;
        const angle = Math.random() * Math.PI * 2;
        // Random speed for explosion spread
        const speed = Math.random() * 5 + 2; 
        this.vx = Math.cos(angle) * speed;
        this.vy = Math.sin(angle) * speed;
        this.alpha = 1;
        this.color = color;
        this.decay = Math.random() * 0.015 + 0.015;
      }

      update() {
        this.x += this.vx;
        this.y += this.vy;
        this.vy += 0.15; // Gravity
        this.vx *= 0.95; // Friction
        this.vy *= 0.95;
        this.alpha -= this.decay;
      }

      draw() {
        ctx!.save();
        ctx!.globalAlpha = this.alpha;
        ctx!.fillStyle = this.color;
        ctx!.beginPath();
        ctx!.arc(this.x, this.y, 2, 0, Math.PI * 2);
        ctx!.fill();
        ctx!.restore();
      }
    }

    class Rocket {
      x: number;
      y: number;
      vy: number;
      color: string;
      exploded: boolean;

      constructor() {
        this.x = Math.random() * width;
        this.y = height;
        // Launch speed depending on screen height
        this.vy = -(Math.random() * (height * 0.015) + (height * 0.02)); 
        this.color = colors[Math.floor(Math.random() * colors.length)];
        this.exploded = false;
      }

      update() {
        this.y += this.vy;
        this.vy += 0.2; // Gravity applied to rocket
      }

      draw() {
        ctx!.save();
        ctx!.fillStyle = this.color;
        ctx!.beginPath();
        // Rocket tail/body
        ctx!.fillRect(this.x - 1, this.y, 3, 10);
        ctx!.restore();
      }
    }

    const particles: Particle[] = [];
    const rockets: Rocket[] = [];

    const loop = () => {
      // Create trails
      ctx.globalCompositeOperation = 'destination-out';
      ctx.fillStyle = 'rgba(0, 0, 0, 0.2)'; // Adjust for trail length
      ctx.fillRect(0, 0, width, height);
      ctx.globalCompositeOperation = 'lighter';

      // Spawn rockets randomly
      if (Math.random() < 0.03) {
        rockets.push(new Rocket());
      }

      // Update and draw rockets
      for (let i = rockets.length - 1; i >= 0; i--) {
        const r = rockets[i];
        r.update();
        r.draw();

        // Explode condition (when velocity slows down near peak)
        if (r.vy >= -1) {
          for (let j = 0; j < 80; j++) {
            particles.push(new Particle(r.x, r.y, r.color));
          }
          rockets.splice(i, 1);
        } else if (r.y < -50) {
           // Cleanup if it goes off screen without exploding (rare)
          rockets.splice(i, 1);
        }
      }

      // Update and draw particles
      for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.update();
        p.draw();
        if (p.alpha <= 0) {
          particles.splice(i, 1);
        }
      }

      animationId = requestAnimationFrame(loop);
    };

    loop();

    return () => {
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(animationId);
    };
  }, []);

  return <canvas ref={canvasRef} className="fixed inset-0 pointer-events-none z-50" />;
};

export default Fireworks;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { TIMEZONES, TARGET_DATE_UTC, TARGET_YEAR } from './constants';
import { TransitionStatus, CelebrationInsight } from './types';
import TimeCard from './components/TimeCard';
import InsightPanel from './components/InsightPanel';
import Fireworks from './components/Fireworks';
import { getCelebrationInsight } from './services/geminiService';
import { Globe, Timer, Search, LayoutGrid, List, MapPin, Sparkles } from 'lucide-react';

const formatFullCountdown = (ms: number) => {
  if (ms <= 0) return "00:00:00:00";
  const seconds = Math.floor((ms / 1000) % 60);
  const minutes = Math.floor((ms / (1000 * 60)) % 60);
  const hours = Math.floor((ms / (1000 * 60 * 60)) % 24);
  const days = Math.floor(ms / (1000 * 60 * 60 * 24));

  const pad = (n: number) => n.toString().padStart(2, '0');
  return `${pad(days)}:${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;
};

const App: React.FC = () => {
  const [now, setNow] = useState(new Date());
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [selectedCountry, setSelectedCountry] = useState<string | null>(null);
  const [insight, setInsight] = useState<CelebrationInsight | null>(null);
  const [loadingInsight, setLoadingInsight] = useState(false);
  const [localStatus, setLocalStatus] = useState<TransitionStatus | null>(null);

  // Update real-time clock
  useEffect(() => {
    const interval = setInterval(() => {
      setNow(new Date());
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // Calculate statuses for all tracked zones
  const statuses = useMemo(() => {
    return TIMEZONES.map(tz => {
      const formatter = new Intl.DateTimeFormat('en-US', {
        timeZone: tz.zone,
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });

      const localTimeStr = formatter.format(now);
      const zoneStartUTC = TARGET_DATE_UTC - (tz.offset * 60 * 1000);
      const timeTo2026 = zoneStartUTC - now.getTime();
      const isIn2026 = timeTo2026 <= 0;

      return {
        ...tz,
        isIn2026,
        localTime: localTimeStr,
        timeTo2026,
        offset: tz.offset
      } as TransitionStatus;
    }).sort((a, b) => b.offset - a.offset);
  }, [now]);

  // Handle local timezone detection and precise countdown
  useEffect(() => {
    try {
      const userZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
      const formatter = new Intl.DateTimeFormat('en-US', {
        timeZone: userZone,
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });
      const localTimeStr = formatter.format(now);
      const isIn2026 = now.getFullYear() >= TARGET_YEAR;

      // Calculate countdown to the local start of 2026
      const startOf2026Local = new Date(TARGET_YEAR, 0, 1, 0, 0, 0);
      const timeTo2026 = startOf2026Local.getTime() - now.getTime();
      const userOffset = -new Date().getTimezoneOffset();

      setLocalStatus({
        zone: userZone,
        country: 'Local Horizon',
        isIn2026,
        localTime: localTimeStr,
        timeTo2026,
        offset: userOffset
      });
    } catch (e) {
      console.warn("Could not determine local timezone");
    }
  }, [now]);

  const handleCountryClick = useCallback(async (country: string) => {
    setSelectedCountry(country);
    setLoadingInsight(true);
    const result = await getCelebrationInsight(country);
    setInsight(result);
    setLoadingInsight(false);
  }, []);

  const filteredStatuses = useMemo(() => {
    return statuses.filter(s => 
      s.country.toLowerCase().includes(searchTerm.toLowerCase()) ||
      s.zone.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [statuses, searchTerm]);

  const stats = useMemo(() => {
    const in2026 = statuses.filter(s => s.isIn2026).length;
    return {
      in2026,
      remaining: statuses.length - in2026,
      next: statuses.find(s => !s.isIn2026)
    };
  }, [statuses]);

  return (
    <div className="min-h-screen bg-black text-slate-100 selection:bg-blue-500/30">
      {/* Show Fireworks if local user is in 2026 */}
      {localStatus?.isIn2026 && <Fireworks />}

      <header className="sticky top-0 z-40 bg-black/50 backdrop-blur-md border-b border-white/5">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center shadow-lg shadow-blue-900/20">
              <Globe className="text-white" size={24} />
            </div>
            <div>
              <h1 className="text-xl font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">
                2026 TRACKER
              </h1>
            </div>
          </div>

          <div className="hidden md:flex items-center gap-6 text-sm font-medium text-slate-400">
            <div className="flex items-center gap-2 px-3 py-1.5 bg-white/5 rounded-full border border-white/5">
              <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
              <span>Live Updates</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-white">{stats.in2026}</span> Countries in 2026
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-12">
          <div className="lg:col-span-2 relative overflow-hidden bg-gradient-to-br from-slate-900 to-slate-950 rounded-3xl p-8 border border-white/10 shadow-2xl">
            <div className="relative z-10">
              <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-blue-500/10 text-blue-400 rounded-full border border-blue-500/20 text-xs font-bold uppercase tracking-widest mb-4">
                <Sparkles size={14} />
                Global Transition Phase
              </div>
              <h2 className="text-4xl md:text-6xl font-black text-white mb-2">Countdown to 2026</h2>
              <p className="text-slate-400 max-w-lg mb-8">Tracking the world's journey into the new year. Explore how different cultures celebrate this historic transition.</p>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                {localStatus && (
                  <div className={`backdrop-blur-xl p-5 rounded-2xl border transition-all duration-500 group shadow-xl ${
                    localStatus.isIn2026 
                      ? 'bg-emerald-950/40 border-emerald-500/30' 
                      : 'bg-black/60 border-white/10 hover:border-blue-500/30'
                  }`}>
                    <p className={`text-xs uppercase tracking-widest font-bold mb-3 flex items-center gap-2 ${
                      localStatus.isIn2026 ? 'text-emerald-400' : 'text-slate-500'
                    }`}>
                      <MapPin size={14} className={localStatus.isIn2026 ? "text-emerald-400" : "text-blue-400"} /> Your Local Time
                    </p>
                    <div className="flex flex-col">
                      <span className={`text-4xl font-mono font-black tracking-tighter ${
                         localStatus.isIn2026 
                          ? 'bg-clip-text text-transparent bg-gradient-to-r from-emerald-300 to-emerald-500' 
                          : 'text-white'
                      }`}>
                        {localStatus.isIn2026 ? "HAPPY 2026!" : formatFullCountdown(localStatus.timeTo2026)}
                      </span>
                      <span className="text-xs text-slate-500 font-mono mt-2 uppercase">
                        Days : Hours : Mins : Secs
                      </span>
                    </div>
                    {!localStatus.isIn2026 && (
                      <div className="mt-4 pt-4 border-t border-white/5">
                        <p className="text-xs text-slate-400">Current Time: <span className="text-white font-mono">{localStatus.localTime}</span></p>
                      </div>
                    )}
                  </div>
                )}

                {stats.next && (
                  <div className="bg-blue-600/5 p-5 rounded-2xl border border-blue-500/10 shadow-xl hover:bg-blue-600/10 transition-all">
                    <p className="text-xs text-blue-400 uppercase tracking-widest font-bold mb-3 flex items-center gap-2">
                      <Timer size={14} /> Next Arrival
                    </p>
                    <p className="text-2xl font-black text-white truncate mb-1">{stats.next.country}</p>
                    <p className="text-sm text-slate-400 font-mono">
                      In {Math.floor(stats.next.timeTo2026 / 1000 / 60)} minutes
                    </p>
                    <div className="mt-4 h-1 w-full bg-white/5 rounded-full overflow-hidden">
                      <div className="h-full bg-blue-500 animate-pulse-slow" style={{ width: '65%' }}></div>
                    </div>
                  </div>
                )}
              </div>
            </div>

            <div className="absolute top-0 right-0 w-1/2 h-full bg-blue-600/5 blur-[120px] rounded-full"></div>
            <div className="absolute bottom-0 left-0 w-1/3 h-1/2 bg-indigo-600/5 blur-[100px] rounded-full"></div>
          </div>

          <div className="bg-slate-900/50 rounded-3xl p-6 border border-white/5 flex flex-col justify-between">
            <div>
              <h3 className="text-lg font-bold text-white mb-4">Global Status</h3>
              <div className="space-y-4">
                <div className="flex justify-between items-center p-3 bg-white/5 rounded-xl">
                  <span className="text-slate-400 text-sm">Countries in 2026</span>
                  <span className="text-xl font-bold text-emerald-400">{stats.in2026}</span>
                </div>
                <div className="flex justify-between items-center p-3 bg-white/5 rounded-xl">
