const formatFullCountdownParts = (ms: number) => {
  if (ms <= 0) return { days: "00", hours: "00", minutes: "00", seconds: "00" };
  const seconds = Math.floor((ms / 1000) % 60);
  const minutes = Math.floor((ms / (1000 * 60)) % 60);
  const hours = Math.floor((ms / (1000 * 60 * 60)) % 24);
  const days = Math.floor(ms / (1000 * 60 * 60 * 24));

  const pad = (n: number) => n.toString().padStart(2, '0');
  return { 
    days: pad(days), 
    hours: pad(hours), 
    minutes: pad(minutes), 
    seconds: pad(seconds) 
  };
};

// Sound effect generator using Web Audio API
const playCelebrationSound = () => {
  try {
    const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
    if (!AudioContext) return;

    const ctx = new AudioContext();
    if (ctx.state === 'suspended') ctx.resume().catch(() => {});

    const now = ctx.currentTime;

    // 1. Play a celebratory chord
    const notes = [523.25, 659.25, 783.99, 1046.50];
    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, now + (i * 0.1));
      gain.gain.setValueAtTime(0, now + (i * 0.1));
      gain.gain.linearRampToValueAtTime(0.1, now + (i * 0.1) + 0.1);
      gain.gain.exponentialRampToValueAtTime(0.001, now + (i * 0.1) + 2);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now + (i * 0.1));
      osc.stop(now + (i * 0.1) + 2);
    });

    // 2. Add some subtle "firework pops"
    const createPop = (time: number) => {
      const bufferSize = ctx.sampleRate * 0.1; 
      const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;

      const noise = ctx.createBufferSource();
      noise.buffer = buffer;
      const noiseGain = ctx.createGain();
      const filter = ctx.createBiquadFilter();

      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(1000, time);
      filter.frequency.exponentialRampToValueAtTime(100, time + 0.1);

      noise.connect(filter);
      filter.connect(noiseGain);
      noiseGain.connect(ctx.destination);
      noiseGain.gain.setValueAtTime(0.05, time);
      noiseGain.gain.exponentialRampToValueAtTime(0.001, time + 0.1);
      noise.start(time);
      noise.stop(time + 0.1);
    };

    for(let i = 0; i < 8; i++) createPop(now + 0.5 + Math.random() * 2);
  } catch (e) {
    console.error("Audio playback failed", e);
  }
};

const playCountdownBeep = () => {
    try {
        const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
        if (!AudioContext) return;

        // We create a new context per beep to ensure it's fresh, or manage a persistent one globally.
        // For simplicity/reliability in this effect loop:
        const ctx = new AudioContext();
        if (ctx.state === 'suspended') ctx.resume().catch(() => {});

        const osc = ctx.createOscillator();
        const gain = ctx.createGain();

        osc.type = 'sine';
        osc.frequency.setValueAtTime(880, ctx.currentTime); // High A (880Hz)

        gain.gain.setValueAtTime(0.05, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.15);

        osc.connect(gain);
        gain.connect(ctx.destination);

        osc.start(ctx.currentTime);
        osc.stop(ctx.currentTime + 0.15);

    } catch (e) {
        // Ignore audio errors (interaction policy)
    }
}

