// Singleton AudioContext and AnalyserNode
let audioCtx: AudioContext | null = null;
let analyser: AnalyserNode | null = null;

export const initAudio = () => {
  if (!audioCtx) {
    const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
    if (AudioContext) {
      audioCtx = new AudioContext();
      analyser = audioCtx.createAnalyser();
      analyser.fftSize = 256; // Use a small FFT size for performance and simple volume detection
      analyser.smoothingTimeConstant = 0.5;

      // Important: Connect analyser to destination so sound is heard
      analyser.connect(audioCtx.destination);
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {});
  }
  return { audioCtx, analyser };
};

export const getAnalyser = () => analyser;

export const playCountdownBeep = () => {
    try {
        const { audioCtx, analyser } = initAudio();
        if (!audioCtx || !analyser) return;

        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();

        // 600Hz subtle beep
        osc.type = 'sine';
        osc.frequency.setValueAtTime(600, audioCtx.currentTime);

        gain.gain.setValueAtTime(0.05, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.15);

        // Connect: Source -> Gain -> Analyser -> Destination
        osc.connect(gain);
        gain.connect(analyser); 

        osc.start(audioCtx.currentTime);
        osc.stop(audioCtx.currentTime + 0.15);
    } catch (e) {
        // Ignore errors
    }
};

export const playCelebrationSound = () => {
  try {
    const { audioCtx, analyser } = initAudio();
    if (!audioCtx || !analyser) return;

    const now = audioCtx.currentTime;

    // 1. Play a celebratory chord
    const notes = [523.25, 659.25, 783.99, 1046.50];
    notes.forEach((freq, i) => {
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, now + (i * 0.1));

      gain.gain.setValueAtTime(0, now + (i * 0.1));
      gain.gain.linearRampToValueAtTime(0.1, now + (i * 0.1) + 0.1);
      gain.gain.exponentialRampToValueAtTime(0.001, now + (i * 0.1) + 2);

      osc.connect(gain);
      gain.connect(analyser!); // Connect to analyser

      osc.start(now + (i * 0.1));
      osc.stop(now + (i * 0.1) + 2);
    });

    // 2. Add some subtle "firework pops"
    const createPop = (time: number) => {
      const bufferSize = audioCtx!.sampleRate * 0.1; 
      const buffer = audioCtx!.createBuffer(1, bufferSize, audioCtx!.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;

      const noise = audioCtx!.createBufferSource();
      noise.buffer = buffer;
      const noiseGain = audioCtx!.createGain();
      const filter = audioCtx!.createBiquadFilter();

      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(1000, time);
      filter.frequency.exponentialRampToValueAtTime(100, time + 0.1);

      noise.connect(filter);
      filter.connect(noiseGain);
      noiseGain.connect(analyser!); // Connect to analyser

      noiseGain.gain.setValueAtTime(0.05, time);
      noiseGain.gain.exponentialRampToValueAtTime(0.001, time + 0.1);
      noise.start(time);
      noise.stop(time + 0.1);
    };

    for(let i = 0; i < 8; i++) createPop(now + 0.5 + Math.random() * 2);
  } catch (e) {
    console.error("Audio playback failed", e);
  }
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
