import React, { useEffect, useRef } from 'react';
import { getAnalyser } from '../services/audioService';

const Background: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = window.innerWidth;
    let height = window.innerHeight;

    const resize = () => {
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = width;
      canvas.height = height;
    };

    window.addEventListener('resize', resize);
    resize();

    // Particle System
    class Star {
      x: number;
      y: number;
      size: number;
      baseAlpha: number;
      currentAlpha: number;
      velocity: number;

      constructor() {
        this.x = Math.random() * width;
        this.y = Math.random() * height;
        this.size = Math.random() * 1.5 + 0.5;
        this.baseAlpha = Math.random() * 0.3 + 0.1;
        this.currentAlpha = this.baseAlpha;
        this.velocity = Math.random() * 0.05 + 0.02;
      }

      update(intensity: number) {
        // Natural drift
        this.y -= this.velocity;
        if (this.y < 0) this.y = height;

        // Audio reactivity: Shimmer
        // Intensity is roughly 0-255. Threshold around 10-20 detects any sound.
        if (intensity > 15) {
            // Boost alpha based on intensity
            const boost = (intensity / 255) * 2; 
            // Randomly select some stars to sparkle more
            if (Math.random() > 0.7) {
                this.currentAlpha = Math.min(1, this.baseAlpha + boost);
            }
        } else {
            // Decay back to base alpha
            if (this.currentAlpha > this.baseAlpha) {
                this.currentAlpha -= 0.05;
            }
            if (this.currentAlpha < this.baseAlpha) {
                this.currentAlpha = this.baseAlpha;
            }
        }
      }

      draw() {
        ctx!.fillStyle = `rgba(255, 255, 255, ${this.currentAlpha})`;
        ctx!.beginPath();
        ctx!.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx!.fill();
      }
    }

    const stars: Star[] = Array.from({ length: 150 }, () => new Star());
    let animationId: number;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // Get audio data
      let averageIntensity = 0;
      const analyser = getAnalyser();
      if (analyser) {
        const dataArray = new Uint8Array(analyser.frequencyBinCount);
        analyser.getByteFrequencyData(dataArray);
        // Calculate average volume
        let sum = 0;
        for (let i = 0; i < dataArray.length; i++) {
            sum += dataArray[i];
        }
        averageIntensity = sum / dataArray.length;
      }

      stars.forEach(star => {
        star.update(averageIntensity);
        star.draw();
      });

      animationId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(animationId);
    };
  }, []);

  return (
    <div className="fixed inset-0 z-[-1] overflow-hidden pointer-events-none bg-[#050505]">
      {/* Base: Deep Gradient */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_top,_var(--tw-gradient-stops))] from-[#1a103c] via-[#050505] to-black opacity-80"></div>

      {/* Canvas Layer for Audio-Reactive Particles */}
      <canvas ref={canvasRef} className="absolute inset-0 w-full h-full mix-blend-screen" />

      {/* Festive Bokeh Orbs - Warmer tones (Gold, Purple, Pink) */}
      <div className="absolute top-[-20%] left-[-10%] w-[70%] h-[70%] bg-fuchsia-900/20 rounded-full blur-[120px] animate-pulse-slow"></div>
      <div className="absolute bottom-[-20%] right-[-10%] w-[70%] h-[70%] bg-indigo-900/20 rounded-full blur-[120px] animate-pulse-slow" style={{ animationDelay: '2s' }}></div>

      {/* Golden Glow for New Year Celebration vibe */}
      <div className="absolute top-[20%] right-[10%] w-[40%] h-[40%] bg-amber-600/10 rounded-full blur-[100px] animate-pulse-slow" style={{ animationDelay: '1s' }}></div>
      <div className="absolute bottom-[10%] left-[10%] w-[30%] h-[30%] bg-rose-900/10 rounded-full blur-[80px]"></div>

      {/* Static Sparkles / Distant Confetti Pattern (CSS Fallback/Layer) */}
      <div className="absolute inset-0 opacity-40 mix-blend-screen" 
           style={{
             backgroundImage: `
               radial-gradient(1.5px 1.5px at 20px 30px, rgba(255, 255, 255, 0.9) 50%, transparent 0),
               radial-gradient(2px 2px at 90px 80px, rgba(251, 191, 36, 0.6) 50%, transparent 0),
               radial-gradient(2px 2px at 160px 120px, rgba(232, 121, 249, 0.5) 50%, transparent 0),
               radial-gradient(1.5px 1.5px at 200px 40px, rgba(255, 255, 255, 0.7) 50%, transparent 0)
             `,
             backgroundSize: '250px 250px',
             animation: 'pulse-slow 5s ease-in-out infinite alternate'
           }}>
      </div>

      {/* Vignette for focus */}
      <div className="absolute inset-0 bg-[radial-gradient(transparent_0%,_#000000_100%)] opacity-60"></div>
    </div>
  );
};

