import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { TIMEZONES, TARGET_DATE_UTC, TARGET_YEAR } from './constants';
import { TransitionStatus, CelebrationInsight } from './types';
import TimeCard from './components/TimeCard';
import InsightPanel from './components/InsightPanel';
import Fireworks from './components/Fireworks';
import Background from './components/Background';
import { getCelebrationInsight } from './services/geminiService';
import { 
  initAudio, 
  playCelebrationSound, 
  playCountdownBeep, 
  playTick, 
  playRandomEffect 
} from './services/audioService';
import { Globe, Timer, Search, LayoutGrid, List, MapPin, Sparkles, CheckCircle2, Clock } from 'lucide-react';

const formatFullCountdownParts = (ms: number) => {
  if (ms <= 0) return { days: "00", hours: "00", minutes: "00", seconds: "00" };
  const seconds = Math.floor((ms / 1000) % 60);
  const minutes = Math.floor((ms / (1000 * 60)) % 60);
  const hours = Math.floor((ms / (1000 * 60 * 60)) % 24);
  const days = Math.floor(ms / (1000 * 60 * 60 * 24));

  const pad = (n: number) => n.toString().padStart(2, '0');
  return { 
    days: pad(days), 
    hours: pad(hours), 
    minutes: pad(minutes), 
    seconds: pad(seconds) 
  };
};

const App: React.FC = () => {
  const [now, setNow] = useState(new Date());
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [selectedCountry, setSelectedCountry] = useState<string | null>(null);
  const [insight, setInsight] = useState<CelebrationInsight | null>(null);
  const [loadingInsight, setLoadingInsight] = useState(false);
  const [localStatus, setLocalStatus] = useState<TransitionStatus | null>(null);
  const [showFireworks, setShowFireworks] = useState(false);
  const lastAudioSecondRef = useRef<number>(-1);

  // Initialize audio context on first user interaction to unlock audio
  useEffect(() => {
    const handleInteraction = () => {
      initAudio();
    };
    window.addEventListener('click', handleInteraction, { once: true });
    window.addEventListener('keydown', handleInteraction, { once: true });
    return () => {
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };
  }, []);

  // Update real-time clock
  useEffect(() => {
    const interval = setInterval(() => {
      setNow(new Date());
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // Calculate statuses for all tracked zones
  const statuses = useMemo(() => {
    return TIMEZONES.map(tz => {
      const formatter = new Intl.DateTimeFormat('en-US', {
        timeZone: tz.zone,
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });

      const localTimeStr = formatter.format(now);
      const zoneStartUTC = TARGET_DATE_UTC - (tz.offset * 60 * 1000);
      const timeTo2026 = zoneStartUTC - now.getTime();
      const isIn2026 = timeTo2026 <= 0;

      return {
        ...tz,
        isIn2026,
        localTime: localTimeStr,
        timeTo2026,
        offset: tz.offset
      } as TransitionStatus;
    }).sort((a, b) => b.offset - a.offset);
  }, [now]);

  // Handle local timezone detection, precise countdown, and audio cues
  useEffect(() => {
    try {
      const userZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
      const formatter = new Intl.DateTimeFormat('en-US', {
        timeZone: userZone,
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });
      const localTimeStr = formatter.format(now);
      const isIn2026 = now.getFullYear() >= TARGET_YEAR;

      const startOf2026Local = new Date(TARGET_YEAR, 0, 1, 0, 0, 0);
      const timeTo2026 = startOf2026Local.getTime() - now.getTime();
      const userOffset = -new Date().getTimezoneOffset();

      // --- AUDIO CUES ---
      if (timeTo2026 > 0 && timeTo2026 <= 60000) {
        // Use ceil so 9.5s remaining counts as "10"
        const currentSecond = Math.ceil(timeTo2026 / 1000);

        if (currentSecond !== lastAudioSecondRef.current) {
             if (currentSecond <= 10) {
                 // Final 10 seconds: Countdown Beep
                 playCountdownBeep();
             } else {
                 // Final Minute (60s to 11s): Subtle Tick
                 playTick();
             }
             lastAudioSecondRef.current = currentSecond;
        }
      }

      setLocalStatus({
        zone: userZone,
        country: 'Local Horizon',
        code: 'UN', 
        isIn2026,
        localTime: localTimeStr,
        timeTo2026,
        offset: userOffset
      });
    } catch (e) {
      console.warn("Could not determine local timezone");
    }
  }, [now]);

  // Trigger fireworks and celebration sound
  useEffect(() => {
    if (localStatus?.isIn2026) {
      if (!showFireworks) {
        setShowFireworks(true);
        playCelebrationSound();
        const timer = setTimeout(() => {
          setShowFireworks(false);
        }, 20000);
        return () => clearTimeout(timer);
      }
    } else {
      setShowFireworks(false);
    }
  }, [localStatus?.isIn2026]);

  // Random Atmospheric Sounds during Fireworks
  useEffect(() => {
    if (showFireworks) {
        const interval = setInterval(() => {
            // 40% chance every 800ms to play a random ambient effect
            if (Math.random() > 0.6) {
                playRandomEffect();
            }
        }, 800);
        return () => clearInterval(interval);
    }
  }, [showFireworks]);

  const handleCountryClick = useCallback(async (country: string) => {
    setSelectedCountry(country);
    setLoadingInsight(true);
    const result = await getCelebrationInsight(country);
    setInsight(result);
    setLoadingInsight(false);
  }, []);

  const filteredStatuses = useMemo(() => {
    return statuses.filter(s => 
      s.country.toLowerCase().includes(searchTerm.toLowerCase()) ||
      s.zone.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [statuses, searchTerm]);

  const arrivedCountries = useMemo(() => filteredStatuses.filter(s => s.isIn2026), [filteredStatuses]);
  const upcomingCountries = useMemo(() => filteredStatuses.filter(s => !s.isIn2026), [filteredStatuses]);

  const stats = useMemo(() => {
    const in2026 = statuses.filter(s => s.isIn2026).length;
    return {
      in2026,
      remaining: statuses.length - in2026,
      next: statuses.find(s => !s.isIn2026)
    };
  }, [statuses]);

  // Breakdown for Hero Animation
  const countdownParts = localStatus 
    ? formatFullCountdownParts(localStatus.timeTo2026) 
    : { days: "00", hours: "00", minutes: "00", seconds: "00" };

  return (
    <div className="min-h-screen text-slate-100 selection:bg-blue-500/30 relative">
      <Background />
      {showFireworks && <Fireworks />}

      <header className="sticky top-0 z-40 bg-black/30 backdrop-blur-md border-b border-white/5">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center shadow-lg shadow-blue-900/20 ring-1 ring-white/10">
              <Globe className="text-white" size={24} />
            </div>
            <div>
              <h1 className="text-xl font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">
                2026 TRACKER
              </h1>
            </div>
          </div>

          <div className="hidden md:flex items-center gap-6 text-sm font-medium text-slate-400">
            <div className="flex items-center gap-2 px-3 py-1.5 bg-white/5 rounded-full border border-white/5 backdrop-blur-sm">
              <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
              <span>Live Updates</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-white">{stats.in2026}</span> Countries in 2026
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 relative z-10">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-12">
          {/* HERO CARD */}
          <div className="lg:col-span-2 relative overflow-hidden bg-slate-900/40 backdrop-blur-md rounded-3xl p-8 border border-white/10 shadow-2xl group">
            <div className="relative z-10">
              <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-blue-500/10 text-blue-400 rounded-full border border-blue-500/20 text-xs font-bold uppercase tracking-widest mb-4">
                <Sparkles size={14} />
                Global Transition Phase
              </div>
              <h2 className="text-4xl md:text-5xl lg:text-6xl font-black text-white mb-2 tracking-tight">Countdown to 2026</h2>
              <p className="text-slate-400 max-w-lg mb-8">Tracking the world's journey into the new year. Explore how different cultures celebrate this historic transition.</p>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {localStatus && (
                  <div className={`backdrop-blur-xl p-6 rounded-2xl border transition-all duration-500 shadow-xl ${
                    localStatus.isIn2026 
                      ? 'bg-emerald-950/40 border-emerald-500/30' 
                      : 'bg-black/40 border-white/10 hover:border-blue-500/30'
                  }`}>
                    <p className={`text-xs uppercase tracking-widest font-bold mb-4 flex items-center gap-2 ${
                      localStatus.isIn2026 ? 'text-emerald-400' : 'text-slate-500'
                    }`}>
                      <MapPin size={14} className={localStatus.isIn2026 ? "text-emerald-400" : "text-blue-400"} /> Your Local Time
                    </p>

                    {/* ANIMATED COUNTDOWN DISPLAY */}
                    <div className="flex flex-col">
                        {localStatus.isIn2026 ? (
                           <span className="text-4xl md:text-6xl font-mono font-black tracking-tighter bg-clip-text text-transparent bg-gradient-to-r from-emerald-300 to-emerald-500 animate-pop py-4">
                             HAPPY 2026!
                           </span>
                        ) : (
                           // New Countdown Layout
                           <div className="flex flex-wrap items-center justify-center md:justify-start gap-3 sm:gap-4 py-2">
                               {/* Days */}
                               <div className="flex flex-col items-center bg-slate-900/50 p-3 sm:p-4 rounded-xl border border-white/10 backdrop-blur-md min-w-[80px] sm:min-w-[100px] shadow-lg">
                                   <span key={countdownParts.days} className="text-3xl sm:text-4xl md:text-5xl font-mono font-black text-white tracking-tighter animate-slide-up block">
                                       {countdownParts.days}
                                   </span>
                                   <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">Days</span>
