                               <div className="flex flex-col items-center bg-slate-900/50 p-3 sm:p-4 rounded-xl border border-white/10 backdrop-blur-md min-w-[80px] sm:min-w-[100px] shadow-lg">
                                   <span key={countdownParts.minutes} className="text-3xl sm:text-4xl md:text-5xl font-mono font-black text-white tracking-tighter animate-slide-up block">
                                       {countdownParts.minutes}
                                   </span>
                                   <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">Min</span>
                               </div>

                               {/* Seconds */}
                               <div className="flex flex-col items-center bg-gradient-to-b from-slate-900/50 to-amber-900/20 p-3 sm:p-4 rounded-xl border border-amber-500/20 backdrop-blur-md min-w-[80px] sm:min-w-[100px] shadow-lg shadow-amber-900/10 relative overflow-hidden">
                                   <div className="absolute inset-0 bg-amber-500/5"></div>
                                   <span key={countdownParts.seconds} className="text-3xl sm:text-4xl md:text-5xl font-mono font-black text-gradient-gold tracking-tighter animate-slide-up block relative z-10">
                                       {countdownParts.seconds}
                                   </span>
                                   <span className="text-[10px] text-amber-500/80 font-bold uppercase tracking-widest mt-1 relative z-10">Sec</span>
                               </div>
                           </div>
                        )}
                    </div>

                    {!localStatus.isIn2026 && (
                      <div className="mt-4 pt-4 border-t border-white/5 flex items-center gap-2">
                        <Clock size={14} className="text-slate-500" />
                        <span key={localStatus.localTime} className="text-xs font-mono text-slate-300 animate-slide-up">{localStatus.localTime}</span>
                      </div>
                    )}
                  </div>
                )}

                {stats.next && (
                  <div className="bg-blue-600/10 backdrop-blur-md p-6 rounded-2xl border border-blue-500/10 shadow-xl hover:bg-blue-600/20 transition-all">
                    <p className="text-xs text-blue-400 uppercase tracking-widest font-bold mb-3 flex items-center gap-2">
