                  <h2 className="text-2xl font-bold text-white leading-none">Countdown to 2026</h2>
                  <p className="text-sm text-slate-500 mt-1">{upcomingCountries.length} countries awaiting the New Year</p>
                </div>
              </div>
              <div className={viewMode === 'grid' 
                ? "grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4" 
