              <p className="text-sm text-slate-500 font-medium">Real-time New Year Observation Tool</p>
            </div>
          </div>
          <div className="text-sm text-slate-600 text-center md:text-right">
            <p>© {new Date().getFullYear()} Global Horizons. Powered by Gemini AI.</p>
            <p className="mt-1">All times are calculated using the International Date Line standard.</p>
          </div>
        </div>
      </footer>
    </div>
