import { GoogleGenAI, Type } from "@google/genai";
import { CelebrationInsight } from "../types";

export const getCelebrationInsight = async (country: string, language: string = 'English'): Promise<CelebrationInsight | null> => {
  try {
    // Instantiate ai inside the function to ensure up-to-date API key access right before the call
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Provide information about how ${country} celebrates New Year (the transition to 2026). Include a common greeting in their language, one unique tradition, and a fun fact. Respond in ${language}.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            country: { type: Type.STRING },
            tradition: { type: Type.STRING },
            greeting: { type: Type.STRING },
            funFact: { type: Type.STRING },
          },
          required: ["country", "tradition", "greeting", "funFact"]
        },
      },
    });

    // Access .text property directly as per Gemini API guidelines
    if (response.text) {
      return JSON.parse(response.text.trim());
    }
    return null;
  } catch (error) {
    console.error("Error fetching insight from Gemini:", error);
    return null;
  }
};

import React from 'react';
import { TransitionStatus } from '../types';
import { Clock, CheckCircle2, Timer } from 'lucide-react';

interface TimeCardProps {
  status: TransitionStatus;
  onClick: (country: string) => void;
  isSelected: boolean;
  variant?: 'grid' | 'list';
  t: any;
}

const formatRemainingCompact = (ms: number, dayLabel: string) => {
  if (ms <= 0) return "IN 2026!";
  const seconds = Math.floor((ms / 1000) % 60);
  const minutes = Math.floor((ms / (1000 * 60)) % 60);
  const hours = Math.floor((ms / (1000 * 60 * 60)) % 24);
  const days = Math.floor(ms / (1000 * 60 * 60 * 24));

  const pad = (n: number) => n.toString().padStart(2, '0');

  // Compact format: "3d 04:20:10" or "04:20:10"
  if (days > 0) return `${days}${dayLabel} ${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;
  return `${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;
};

const TimeCard: React.FC<TimeCardProps> = ({ status, onClick, isSelected, variant = 'grid', t }) => {
  // Extract just the time portion from the full date string
  const timePart = status.localTime.split(',').pop()?.trim() || status.localTime;
  const isList = variant === 'list';
  const remainingText = formatRemainingCompact(status.timeTo2026, t.dayShort);

  if (isList) {
    return (
      <div 
        onClick={() => onClick(status.country)}
        className={`relative overflow-hidden cursor-pointer transition-all duration-300 p-3 rounded-lg border flex items-center justify-between gap-4 backdrop-blur-sm ${
          status.isIn2026 
            ? 'bg-emerald-950/40 border-emerald-500/30 hover:bg-emerald-900/50' 
            : 'bg-slate-900/40 border-slate-700/50 hover:border-blue-500/50 hover:bg-slate-800/50'
        } ${isSelected ? 'ring-2 ring-blue-500' : ''} group`}
      >
        {/* Left: Identity */}
        <div className="flex items-center gap-3 min-w-0">
          <div className="flex-shrink-0 w-8 h-6 rounded flex items-center justify-center border border-white/10 overflow-hidden bg-slate-800 shadow-sm">
            <img 
              src={`https://flagcdn.com/w80/${status.code.toLowerCase()}.png`}
              alt={`${status.country} flag`}
              className="w-full h-full object-cover"
            />
          </div>
          <div className="min-w-0 flex flex-col">
            <div className="flex items-center gap-2">
              <h3 className="text-sm font-bold tracking-tight text-white leading-tight truncate">{status.country}</h3>
              {status.isIn2026 ? (
                <CheckCircle2 className="text-emerald-400 w-4 h-4 animate-pulse md:hidden" />
              ) : (
                <Timer className="text-blue-400 w-4 h-4 md:hidden" />
              )}
            </div>
            <p className="text-[10px] text-slate-400 font-mono truncate opacity-70">{status.zone}</p>
          </div>
        </div>

        {/* Right: Data */}
        <div className="flex items-center gap-6 flex-shrink-0">
          {/* Local Time (Hidden on very small screens to save space) */}
          <div className="hidden sm:flex items-center gap-2 text-slate-400">
            <Clock size={14} />
            <span key={timePart} className="text-xs font-mono font-medium animate-tick tabular-nums">{timePart}</span>
          </div>

          {/* Countdown/Status */}
          <div className="text-right min-w-[80px]">
             <div className="flex items-center justify-end gap-2 mb-0.5">
                <span className={`text-[10px] font-bold uppercase tracking-wider ${status.isIn2026 ? 'text-emerald-500' : 'text-slate-500'}`}>
                  {status.isIn2026 ? t.cardLive : t.cardToGo}
                </span>
                {status.isIn2026 ? (
                  <CheckCircle2 className="text-emerald-400 w-3 h-3 hidden md:block" />
                ) : (
                  <Timer className="text-blue-400 w-3 h-3 hidden md:block" />
                )}
             </div>
             <p key={remainingText} className={`text-sm font-mono font-bold tracking-tight tabular-nums animate-slide-up ${status.isIn2026 ? 'text-emerald-400' : 'text-blue-400'}`}>
                {remainingText}
             </p>
          </div>
        </div>
      </div>
    );
  }

  // Grid Variant (Default)
  return (
    <div 
      onClick={() => onClick(status.country)}
      className={`relative overflow-hidden cursor-pointer transition-all duration-300 p-4 rounded-xl border backdrop-blur-sm ${
        status.isIn2026 
          ? 'bg-emerald-950/40 border-emerald-500/50 hover:bg-emerald-900/50' 
          : 'bg-slate-900/40 border-slate-700/50 hover:border-blue-500/50 hover:bg-slate-800/50'
      } ${isSelected ? 'ring-2 ring-blue-500' : ''} group`}
    >
      {/* Header: Flag, Country, Zone, Status Icon */}
      <div className="flex justify-between items-start mb-3">
        <div className="flex items-center gap-3 min-w-0">
          <div className="flex-shrink-0 w-8 h-6 rounded flex items-center justify-center border border-white/10 overflow-hidden bg-slate-800 shadow-sm">
            <img 
              src={`https://flagcdn.com/w80/${status.code.toLowerCase()}.png`}
              alt={`${status.country} flag`}
              className="w-full h-full object-cover"
              loading="lazy"
            />
          </div>

          <div className="min-w-0">
            <h3 className="text-sm font-bold tracking-tight text-white leading-tight truncate pr-2">{status.country}</h3>
            <p className="text-[10px] text-slate-400 font-mono truncate opacity-70 group-hover:opacity-100 transition-opacity">{status.zone}</p>
          </div>
        </div>

        {status.isIn2026 ? (
          <CheckCircle2 className="text-emerald-400 w-5 h-5 flex-shrink-0 animate-pulse" />
        ) : (
          <Timer className="text-blue-400 w-5 h-5 flex-shrink-0" />
        )}
      </div>

      {/* Body: Two-column grid for Time and Countdown */}
      <div className="grid grid-cols-2 gap-2 pt-3 border-t border-white/5">
        <div className="flex flex-col justify-center">
          <p className="text-[10px] uppercase tracking-wider text-slate-500 font-bold mb-0.5">{t.cardLocalTime}</p>
          <div className="flex items-center gap-1.5 text-slate-300">
            <Clock size={12} className="text-slate-500" />
            <span key={timePart} className="text-xs font-mono font-medium tracking-tight animate-tick tabular-nums">{timePart}</span>
          </div>
        </div>

        <div className="flex flex-col justify-center text-right">
          <p className={`text-[10px] uppercase tracking-wider font-bold mb-0.5 ${status.isIn2026 ? 'text-emerald-500' : 'text-slate-500'}`}>
            {status.isIn2026 ? t.cardStatus : t.cardCountdown}
          </p>
          <p key={remainingText} className={`text-sm font-mono font-bold tracking-tight tabular-nums animate-slide-up ${status.isIn2026 ? 'text-emerald-400' : 'text-blue-400'}`}>
            {remainingText}
          </p>
        </div>
      </div>

      {/* Background decoration */}
      <div className={`absolute -bottom-6 -right-6 w-20 h-20 rounded-full opacity-5 blur-xl transition-opacity duration-500 group-hover:opacity-10 ${status.isIn2026 ? 'bg-emerald-500' : 'bg-blue-500'}`}></div>
    </div>
  );
};

