import React, { useMemo } from 'react';
import { TimeZoneData, TransitionStatus } from '../types';
import { TARGET_DATE_UTC } from '../constants';
import { Play, Pause, RotateCcw, Clock } from 'lucide-react';

interface TimelineProps {
  timezones: TimeZoneData[];
  currentTime: number;
  onTimeChange: (time: number) => void;
  isSimulating: boolean;
  onToggleSimulation: () => void;
  t: any;
  statuses: TransitionStatus[];
}

const Timeline: React.FC<TimelineProps> = ({ 
  timezones, 
  currentTime, 
  onTimeChange, 
  isSimulating, 
  onToggleSimulation,
  t,
  statuses
}) => {
  // Determine range of timeline
  // Earliest Arrival: UTC+14 => Midnight happens at Dec 31 10:00 UTC
  // Latest Arrival: UTC-12 => Midnight happens at Jan 1 12:00 UTC
  // Add 1 hour buffer on each side
  const START_UTC = TARGET_DATE_UTC - (15 * 60 * 60 * 1000); // Dec 31 09:00 UTC
  const END_UTC = TARGET_DATE_UTC + (13 * 60 * 60 * 1000);   // Jan 1 13:00 UTC
  const DURATION = END_UTC - START_UTC;

  const getPositionPercent = (time: number) => {
    return Math.max(0, Math.min(100, ((time - START_UTC) / DURATION) * 100));
  };

  const handleRangeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newVal = parseInt(e.target.value);
    onTimeChange(newVal);
  };

  // Group countries by arrival time for markers
  const markers = useMemo(() => {
    const map = new Map<number, number>(); // ArrivalTime -> Count
    timezones.forEach(tz => {
      // Arrival Time in UTC = Target - Offset
      const arrivalUTC = TARGET_DATE_UTC - (tz.offset * 60 * 1000);
      map.set(arrivalUTC, (map.get(arrivalUTC) || 0) + 1);
    });

    return Array.from(map.entries()).map(([time, count]) => ({
      time,
      count,
      left: getPositionPercent(time)
    }));
  }, [timezones]);

  const currentPercent = getPositionPercent(currentTime);

  const displayTime = new Intl.DateTimeFormat('en-US', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    timeZone: 'UTC',
    hour12: false
  }).format(new Date(currentTime));

  return (
    <div className="w-full bg-slate-900/60 backdrop-blur-md border-y border-white/5 py-6 px-4 mb-8 relative group select-none">
      <div className="max-w-7xl mx-auto">

        {/* Header / Controls */}
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
             <button 
                onClick={onToggleSimulation}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-bold uppercase tracking-wider transition-all ${
                  isSimulating 
                    ? 'bg-amber-500 text-black hover:bg-amber-400' 
                    : 'bg-white/10 text-slate-300 hover:bg-white/20'
                }`}
             >
                {isSimulating ? (
                  <>
                    <RotateCcw size={12} /> {t.returnToLive}
                  </>
                ) : (
                  <>
                    <Clock size={12} /> {t.simulationMode}
                  </>
                )}
             </button>
             {isSimulating && (
               <span className="text-amber-400 text-xs font-mono animate-pulse">
                  SIMULATION ACTIVE — UTC {displayTime}
               </span>
             )}
          </div>
          <div className="text-xs text-slate-500 font-medium hidden sm:block">
            {isSimulating ? t.dragToTravel : "Timeline of 2026 Arrivals"}
          </div>
        </div>

        {/* Timeline Track */}
        <div className="relative h-12 flex items-center">
            {/* Base Line */}
            <div className="absolute inset-x-0 h-1 bg-white/10 rounded-full"></div>

            {/* Progress Line (Past time) */}
            <div 
              className="absolute left-0 h-1 bg-gradient-to-r from-blue-900 via-blue-600 to-indigo-500 rounded-full transition-all duration-75 ease-linear" 
              style={{ width: `${currentPercent}%` }}
            ></div>

            {/* Event Markers */}
            {markers.map((marker) => (
              <div 
                key={marker.time}
                className={`absolute w-3 h-3 -ml-1.5 rounded-full border-2 transition-all duration-300 transform hover:scale-150 cursor-help z-10 ${
                  currentTime >= marker.time 
                    ? 'bg-emerald-500 border-emerald-900 scale-100' 
                    : 'bg-slate-800 border-slate-600 scale-75 hover:bg-white'
                }`}
                style={{ left: `${marker.left}%`, top: '50%', marginTop: '-6px' }}
                title={`UTC ${new Date(marker.time).toISOString().substr(11, 5)} - ${marker.count} Zones`}
              >
                {/* Tooltip on Hover */}
                <div className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 bg-black text-white text-[10px] px-2 py-1 rounded opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity whitespace-nowrap">
                   {new Date(marker.time).getUTCHours()}:00 UTC
                </div>
              </div>
            ))}

            {/* Scrubber Thumb */}
            <div 
              className={`absolute top-1/2 -mt-3 -ml-3 w-6 h-6 rounded-full shadow-[0_0_15px_rgba(255,255,255,0.5)] border-2 border-white z-20 cursor-grab active:cursor-grabbing transition-colors duration-75 pointer-events-none ${
                isSimulating ? 'bg-amber-500 animate-pulse' : 'bg-blue-500'
              }`}
              style={{ left: `${currentPercent}%` }}
            >
              {isSimulating && (
                 <div className="absolute top-full mt-2 left-1/2 -translate-x-1/2 bg-amber-500 text-black font-bold font-mono text-xs px-2 py-1 rounded shadow-lg whitespace-nowrap">
                    UTC {displayTime}
                 </div>
              )}
            </div>

            {/* Invisible Range Input for Interaction */}
            <input 
              type="range" 
              min={START_UTC} 
              max={END_UTC} 
              step={60 * 1000} // 1 minute steps
              value={currentTime}
              onChange={handleRangeChange}
              onMouseDown={() => !isSimulating && onToggleSimulation()}
              onTouchStart={() => !isSimulating && onToggleSimulation()}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-30"
            />
        </div>

        <div className="flex justify-between mt-2 text-[10px] text-slate-500 font-mono uppercase tracking-widest">
            <span>Dec 31 10:00 UTC</span>
            <span>Jan 01 12:00 UTC</span>
        </div>
      </div>
    </div>
  );
};

export default Timeline;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { TIMEZONES, TARGET_DATE_UTC, TARGET_YEAR, LANGUAGES, TRANSLATIONS, Language } from './constants';
import { TransitionStatus, CelebrationInsight } from './types';
import TimeCard from './components/TimeCard';
import InsightPanel from './components/InsightPanel';
import Fireworks from './components/Fireworks';
import Background from './components/Background';
import Timeline from './components/Timeline';
import { getCelebrationInsight } from './services/geminiService';
import { 
  initAudio, 
  playCelebrationSound, 
  playCountdownBeep, 
  playTick, 
  playRandomEffect 
} from './services/audioService';
import { Globe, Timer, Search, LayoutGrid, List, MapPin, Sparkles, CheckCircle2, Clock, ChevronRight, Languages as LangIcon } from 'lucide-react';

const formatFullCountdownParts = (ms: number) => {
  if (ms <= 0) return { days: "00", hours: "00", minutes: "00", seconds: "00" };
  const seconds = Math.floor((ms / 1000) % 60);
  const minutes = Math.floor((ms / (1000 * 60)) % 60);
  const hours = Math.floor((ms / (1000 * 60 * 60)) % 24);
  const days = Math.floor(ms / (1000 * 60 * 60 * 24));

  const pad = (n: number) => n.toString().padStart(2, '0');
  return { 
    days: pad(days), 
    hours: pad(hours), 
    minutes: pad(minutes), 
    seconds: pad(seconds) 
  };
};

const App: React.FC = () => {
  const [now, setNow] = useState(new Date());
  const [simulationTime, setSimulationTime] = useState<number | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [selectedCountry, setSelectedCountry] = useState<string | null>(null);
  const [insight, setInsight] = useState<CelebrationInsight | null>(null);
  const [loadingInsight, setLoadingInsight] = useState(false);
  const [localStatus, setLocalStatus] = useState<TransitionStatus | null>(null);
  const [showFireworks, setShowFireworks] = useState(false);
  const lastAudioSecondRef = useRef<number>(-1);

  // Language State
  const [language, setLanguage] = useState<Language>('en');
  const t = TRANSLATIONS[language];

  // Derived display time (Real or Simulated)
  const displayTime = useMemo(() => {
    return simulationTime ? new Date(simulationTime) : now;
  }, [now, simulationTime]);

  const isSimulating = simulationTime !== null;

  // Initialize audio context on first user interaction to unlock audio
  useEffect(() => {
    const handleInteraction = () => {
      initAudio();
    };
    window.addEventListener('click', handleInteraction, { once: true });
    window.addEventListener('keydown', handleInteraction, { once: true });
    return () => {
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };
  }, []);

  // Update real-time clock
  useEffect(() => {
    const interval = setInterval(() => {
      setNow(new Date());
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // Calculate statuses for all tracked zones based on displayTime
  const statuses = useMemo(() => {
    return TIMEZONES.map(tz => {
      const formatter = new Intl.DateTimeFormat(language === 'en' ? 'en-US' : language, {
        timeZone: tz.zone,
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });

      const localTimeStr = formatter.format(displayTime);
      const zoneStartUTC = TARGET_DATE_UTC - (tz.offset * 60 * 1000);
      const timeTo2026 = zoneStartUTC - displayTime.getTime();
      const isIn2026 = timeTo2026 <= 0;

      return {
        ...tz,
        isIn2026,
        localTime: localTimeStr,
        timeTo2026,
        offset: tz.offset
      } as TransitionStatus;
    }).sort((a, b) => b.offset - a.offset);
  }, [displayTime, language]);

  // Handle local timezone detection, precise countdown, and audio cues
  useEffect(() => {
    try {
      const userZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
      const formatter = new Intl.DateTimeFormat(language === 'en' ? 'en-US' : language, {
        timeZone: userZone,
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });
      const localTimeStr = formatter.format(displayTime);
      const isIn2026 = displayTime.getFullYear() >= TARGET_YEAR;

      const startOf2026Local = new Date(TARGET_YEAR, 0, 1, 0, 0, 0);
      const timeTo2026 = startOf2026Local.getTime() - displayTime.getTime();
      const userOffset = -new Date().getTimezoneOffset();

      // --- AUDIO CUES (Only when NOT simulating to avoid glitchy sound scrubbing) ---
      if (!isSimulating && timeTo2026 > 0 && timeTo2026 <= 60000) {
        // Use ceil so 9.5s remaining counts as "10"
        const currentSecond = Math.ceil(timeTo2026 / 1000);

        if (currentSecond !== lastAudioSecondRef.current) {
             if (currentSecond <= 10) {
                 // Final 10 seconds: Countdown Beep
                 playCountdownBeep();
             } else {
                 // Final Minute (60s to 11s): Subtle Tick
                 playTick();
             }
             lastAudioSecondRef.current = currentSecond;
        }
      }

      setLocalStatus({
        zone: userZone,
        country: 'Local Horizon',
        code: 'UN', 
        isIn2026,
        localTime: localTimeStr,
        timeTo2026,
        offset: userOffset
      });
    } catch (e) {
      console.warn("Could not determine local timezone");
    }
  }, [displayTime, language, isSimulating]);

  // Trigger fireworks and celebration sound
