        setShowFireworks(true);
        if (!isSimulating) {
           playCelebrationSound();
        }
        const timer = setTimeout(() => {
          setShowFireworks(false);
        }, 20000);
        return () => clearTimeout(timer);
      }
    } else {
      setShowFireworks(false);
    }
