  const filteredStatuses = useMemo(() => {
    return statuses.filter(s => 
      s.country.toLowerCase().includes(searchTerm.toLowerCase()) ||
      s.zone.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [statuses, searchTerm]);

  const arrivedCountries = useMemo(() => filteredStatuses.filter(s => s.isIn2026), [filteredStatuses]);
  const upcomingCountries = useMemo(() => filteredStatuses.filter(s => !s.isIn2026), [filteredStatuses]);

  const stats = useMemo(() => {
    const in2026 = statuses.filter(s => s.isIn2026).length;
    return {
      in2026,
      remaining: statuses.length - in2026,
      next: statuses.find(s => !s.isIn2026)
    };
  }, [statuses]);

  // Breakdown for Hero Animation
  const countdownParts = localStatus 
    ? formatFullCountdownParts(localStatus.timeTo2026) 
    : { days: "00", hours: "00", minutes: "00", seconds: "00" };

  const handleTimeChange = (time: number) => {
    setSimulationTime(time);
  };

  const toggleSimulation = () => {
    if (isSimulating) {
      setSimulationTime(null);
    } else {
      setSimulationTime(now.getTime());
    }
  };

  return (
    <div className={`min-h-screen text-slate-100 selection:bg-blue-500/30 relative transition-colors duration-1000 ${isSimulating ? 'bg-amber-950/20' : ''}`}>
      <Background />
      {showFireworks && <Fireworks />}

      {/* Simulation Overlay Badge */}
      {isSimulating && (
        <div className="fixed top-0 left-0 w-full h-1 bg-amber-500 z-50 animate-pulse shadow-[0_0_15px_rgba(245,158,11,0.5)]"></div>
      )}

      <header className={`sticky top-0 z-40 backdrop-blur-md border-b transition-colors duration-500 ${isSimulating ? 'bg-amber-950/40 border-amber-500/20' : 'bg-black/30 border-white/5'}`}>
