          <div className="flex items-center gap-2">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 transition-all ${isSimulating ? 'bg-gradient-to-br from-amber-600 to-orange-700 ring-amber-500/30' : 'bg-gradient-to-br from-blue-600 to-indigo-700 shadow-blue-900/20 ring-white/10'}`}>
