import React, { useEffect, useRef } from 'react';
import { getAnalyser } from '../services/audioService';

interface BackgroundProps {
  theme: 'dark' | 'light';
}

const Background: React.FC<BackgroundProps> = ({ theme }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = window.innerWidth;
    let height = window.innerHeight;

    const resize = () => {
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = width;
      canvas.height = height;
    };

    window.addEventListener('resize', resize);
    resize();

    const isDark = theme === 'dark';

    // --- Particle Systems ---

    // 1. Stars (High Frequencies)
    class Star {
      x: number;
      y: number;
      size: number;
      baseSize: number;
      baseAlpha: number;
      currentAlpha: number;
      velocity: number;
      color: string;

      constructor() {
        this.x = Math.random() * width;
        this.y = Math.random() * height;
        this.baseSize = Math.random() * 1.5 + 0.5;
        this.size = this.baseSize;
        this.baseAlpha = Math.random() * 0.3 + 0.1;
        this.currentAlpha = this.baseAlpha;
        this.velocity = Math.random() * 0.05 + 0.02;
        this.color = isDark ? '255, 255, 255' : '100, 116, 139'; // White vs Slate-500
      }

      update(energy: number) {
        // High frequency reaction: Sparkle (Alpha) and slight Size increase
        this.y -= this.velocity;
        if (this.y < 0) this.y = height;

        const normalizedEnergy = Math.max(0, (energy - 20) / 255); // Threshold noise

        if (normalizedEnergy > 0) {
            this.currentAlpha = Math.min(1, this.baseAlpha + (normalizedEnergy * 1.5));
            this.size = this.baseSize + (normalizedEnergy * 1.5);
        } else {
            // Decay
            this.currentAlpha += (this.baseAlpha - this.currentAlpha) * 0.1;
            this.size += (this.baseSize - this.size) * 0.1;
        }
      }

      draw() {
        ctx!.fillStyle = `rgba(${this.color}, ${this.currentAlpha})`;
        ctx!.beginPath();
        ctx!.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx!.fill();
      }
    }

    // 2. Confetti (Mid Frequencies)
    class Confetti {
      x: number;
      y: number;
      size: number;
      color: string;
      rotation: number;
      rotationSpeed: number;
      driftX: number;
      driftY: number;

      constructor() {
        this.x = Math.random() * width;
        this.y = Math.random() * height;
        this.size = Math.random() * 4 + 2;
        const darkColors = ['#fcd34d', '#e879f9', '#818cf8']; // Gold, Pink, Indigo
        const lightColors = ['#f59e0b', '#d946ef', '#6366f1']; // Darker variants for light mode
        const colors = isDark ? darkColors : lightColors;
        this.color = colors[Math.floor(Math.random() * colors.length)];
        this.rotation = Math.random() * Math.PI * 2;
        this.rotationSpeed = (Math.random() - 0.5) * 0.02;
        this.driftX = (Math.random() - 0.5) * 0.5;
        this.driftY = Math.random() * 0.5 + 0.2;
      }

      update(energy: number) {
        // Mid frequency reaction: Movement speed and Rotation
        const normalizedEnergy = Math.max(0, (energy - 30) / 255);

        const speedMultiplier = 1 + (normalizedEnergy * 3);

        this.y += this.driftY * speedMultiplier;
        this.x += this.driftX * speedMultiplier;
        this.rotation += this.rotationSpeed * speedMultiplier;

        if (this.y > height) this.y = -10;
        if (this.x > width) this.x = 0;
        if (this.x < 0) this.x = width;
      }

      draw(energy: number) {
        // Opacity reacts slightly
        const normalizedEnergy = Math.max(0, energy / 255);
        const alpha = isDark ? 0.4 + (normalizedEnergy * 0.4) : 0.6 + (normalizedEnergy * 0.3);

        ctx!.save();
        ctx!.translate(this.x, this.y);
        ctx!.rotate(this.rotation);
        ctx!.fillStyle = this.color;
        ctx!.globalAlpha = alpha;
        ctx!.fillRect(-this.size/2, -this.size/2, this.size, this.size);
        ctx!.restore();
      }
    }

    const stars: Star[] = Array.from({ length: 150 }, () => new Star());
    const confetti: Confetti[] = Array.from({ length: 50 }, () => new Confetti());

    let animationId: number;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      let bassEnergy = 0;
      let midEnergy = 0;
      let highEnergy = 0;

      const analyser = getAnalyser();
      if (analyser) {
        const bufferLength = analyser.frequencyBinCount;
        const dataArray = new Uint8Array(bufferLength);
        analyser.getByteFrequencyData(dataArray);

        // Simple frequency banding
        const bassEnd = Math.floor(bufferLength * 0.1); // ~0-10% (Low Bass)
        const midEnd = Math.floor(bufferLength * 0.5);  // ~10-50% (Mids)

        let bSum = 0, mSum = 0, hSum = 0;
        let bCount = 0, mCount = 0, hCount = 0;

        for (let i = 0; i < bufferLength; i++) {
            const val = dataArray[i];
            if (i < bassEnd) { bSum += val; bCount++; }
            else if (i < midEnd) { mSum += val; mCount++; }
            else { hSum += val; hCount++; }
        }

        bassEnergy = bCount > 0 ? bSum / bCount : 0;
        midEnergy = mCount > 0 ? mSum / mCount : 0;
        highEnergy = hCount > 0 ? hSum / hCount : 0;
      }

      // --- Draw Bass Pulse (Background Layer) ---
      if (bassEnergy > 0) {
        const normalizedBass = bassEnergy / 255;
        // Draw a large soft glow in the bottom center
        const gradient = ctx.createRadialGradient(
            width / 2, height, 0,
            width / 2, height, width * 0.8
        );
        // Golden/Warm bass glow
        const alpha = normalizedBass * 0.3; 
        if (isDark) {
            gradient.addColorStop(0, `rgba(217, 119, 6, ${alpha})`); // Amber-600
            gradient.addColorStop(0.5, `rgba(88, 28, 135, ${alpha * 0.5})`); // Purple-900
            gradient.addColorStop(1, 'rgba(0,0,0,0)');
        } else {
             // Blue/Teal pulse for light mode
            gradient.addColorStop(0, `rgba(14, 165, 233, ${alpha})`); // Sky-500
            gradient.addColorStop(0.5, `rgba(99, 102, 241, ${alpha * 0.5})`); // Indigo-500
            gradient.addColorStop(1, 'rgba(255,255,255,0)');
        }

        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, width, height);
      }

      // --- Draw Confetti (Mids) ---
      confetti.forEach(c => {
        c.update(midEnergy);
        c.draw(midEnergy);
      });

      // --- Draw Stars (Highs) ---
      stars.forEach(s => {
        s.update(highEnergy);
        s.draw();
      });

      animationId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(animationId);
    };
  }, [theme]); // Re-run when theme changes

  const isDark = theme === 'dark';

  return (
    <div className={`fixed inset-0 z-[-1] overflow-hidden pointer-events-none transition-colors duration-700 ${isDark ? 'bg-[#050505]' : 'bg-slate-50'}`}>
      {/* Base: Deep Gradient (Static) - Dark Mode */}
      <div className={`absolute inset-0 bg-[radial-gradient(circle_at_top,_var(--tw-gradient-stops))] from-[#1a103c] via-[#050505] to-black transition-opacity duration-1000 ${isDark ? 'opacity-80' : 'opacity-0'}`}></div>

      {/* Base: Light Gradient (Static) - Light Mode */}
       <div className={`absolute inset-0 bg-[radial-gradient(circle_at_top,_var(--tw-gradient-stops))] from-blue-100 via-slate-50 to-white transition-opacity duration-1000 ${isDark ? 'opacity-0' : 'opacity-100'}`}></div>

      {/* Canvas Layer for Audio-Reactive Elements */}
      <canvas ref={canvasRef} className={`absolute inset-0 w-full h-full ${isDark ? 'mix-blend-screen' : 'mix-blend-multiply opacity-50'}`} />

      {/* Static Atmospheric Elements (CSS) */}
      <div className={`absolute top-[-20%] left-[-10%] w-[70%] h-[70%] rounded-full blur-[120px] animate-pulse-slow transition-colors duration-1000 ${isDark ? 'bg-fuchsia-900/10' : 'bg-blue-300/20'}`}></div>
      <div className={`absolute bottom-[-20%] right-[-10%] w-[70%] h-[70%] rounded-full blur-[120px] animate-pulse-slow transition-colors duration-1000 ${isDark ? 'bg-indigo-900/10' : 'bg-indigo-300/20'}`} style={{ animationDelay: '2s' }}></div>

      {/* Vignette - Only visible in dark mode generally, or very subtle in light */}
      <div className={`absolute inset-0 bg-[radial-gradient(transparent_0%,_#000000_100%)] transition-opacity duration-1000 ${isDark ? 'opacity-60' : 'opacity-5'}`}></div>
    </div>
  );
};

export default Background;

import React from 'react';
import { TransitionStatus } from '../types';
import { Clock, CheckCircle2, Timer } from 'lucide-react';

interface TimeCardProps {
  status: TransitionStatus;
  onClick: (country: string) => void;
  isSelected: boolean;
  variant?: 'grid' | 'list';
  t: any;
  theme: 'dark' | 'light';
}

const formatRemainingCompact = (ms: number, dayLabel: string) => {
  if (ms <= 0) return "IN 2026!";
  const seconds = Math.floor((ms / 1000) % 60);
  const minutes = Math.floor((ms / (1000 * 60)) % 60);
  const hours = Math.floor((ms / (1000 * 60 * 60)) % 24);
  const days = Math.floor(ms / (1000 * 60 * 60 * 24));

  const pad = (n: number) => n.toString().padStart(2, '0');

  // Compact format: "3d 04:20:10" or "04:20:10"
  if (days > 0) return `${days}${dayLabel} ${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;
  return `${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;
};

const TimeCard: React.FC<TimeCardProps> = ({ status, onClick, isSelected, variant = 'grid', t, theme }) => {
  // Extract just the time portion from the full date string
  const timePart = status.localTime.split(',').pop()?.trim() || status.localTime;
  const isList = variant === 'list';
  const remainingText = formatRemainingCompact(status.timeTo2026, t.dayShort);
  const isDark = theme === 'dark';

  if (isList) {
    return (
      <div 
        onClick={() => onClick(status.country)}
        className={`relative overflow-hidden cursor-pointer transition-all duration-300 p-3 rounded-lg border flex items-center justify-between gap-4 backdrop-blur-sm ${
          status.isIn2026 
            ? (isDark ? 'bg-emerald-950/40 border-emerald-500/30 hover:bg-emerald-900/50' : 'bg-emerald-50 border-emerald-200 hover:bg-emerald-100')
            : (isDark ? 'bg-slate-900/40 border-slate-700/50 hover:border-blue-500/50 hover:bg-slate-800/50' : 'bg-white border-slate-200 hover:border-blue-300 hover:bg-slate-50 shadow-sm')
        } ${isSelected ? 'ring-2 ring-blue-500' : ''} group`}
      >
        {/* Left: Identity */}
        <div className="flex items-center gap-3 min-w-0">
          <div className={`flex-shrink-0 w-8 h-6 rounded flex items-center justify-center border overflow-hidden shadow-sm ${isDark ? 'bg-slate-800 border-white/10' : 'bg-slate-100 border-slate-200'}`}>
            <img 
              src={`https://flagcdn.com/w80/${status.code.toLowerCase()}.png`}
              alt={`${status.country} flag`}
              className="w-full h-full object-cover"
            />
          </div>
          <div className="min-w-0 flex flex-col">
            <div className="flex items-center gap-2">
              <h3 className={`text-sm font-bold tracking-tight leading-tight truncate ${isDark ? 'text-white' : 'text-slate-900'}`}>{status.country}</h3>
              {status.isIn2026 ? (
                <CheckCircle2 className="text-emerald-500 w-4 h-4 animate-pulse md:hidden" />
              ) : (
                <Timer className="text-blue-500 w-4 h-4 md:hidden" />
              )}
            </div>
            <p className={`text-[10px] font-mono truncate opacity-70 ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>{status.zone}</p>
          </div>
        </div>

        {/* Right: Data */}
        <div className="flex items-center gap-6 flex-shrink-0">
          {/* Local Time (Hidden on very small screens to save space) */}
          <div className={`hidden sm:flex items-center gap-2 ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>
            <Clock size={14} />
            <span key={timePart} className="text-xs font-mono font-medium animate-tick tabular-nums">{timePart}</span>
          </div>

          {/* Countdown/Status */}
          <div className="text-right min-w-[80px]">
             <div className="flex items-center justify-end gap-2 mb-0.5">
                <span className={`text-[10px] font-bold uppercase tracking-wider ${status.isIn2026 ? 'text-emerald-500' : (isDark ? 'text-slate-500' : 'text-slate-500')}`}>
                  {status.isIn2026 ? t.cardLive : t.cardToGo}
                </span>
                {status.isIn2026 ? (
                  <CheckCircle2 className="text-emerald-500 w-3 h-3 hidden md:block" />
                ) : (
                  <Timer className="text-blue-500 w-3 h-3 hidden md:block" />
                )}
             </div>
             <p key={remainingText} className={`text-sm font-mono font-bold tracking-tight tabular-nums animate-slide-up ${status.isIn2026 ? 'text-emerald-500' : 'text-blue-500'}`}>
                {remainingText}
             </p>
          </div>
        </div>
      </div>
    );
  }

  // Grid Variant (Default)
  return (
    <div 
      onClick={() => onClick(status.country)}
      className={`relative overflow-hidden cursor-pointer transition-all duration-300 p-4 rounded-xl border backdrop-blur-sm ${
        status.isIn2026 
          ? (isDark ? 'bg-emerald-950/40 border-emerald-500/50 hover:bg-emerald-900/50' : 'bg-emerald-50/80 border-emerald-200 hover:bg-emerald-100/50') 
          : (isDark ? 'bg-slate-900/40 border-slate-700/50 hover:border-blue-500/50 hover:bg-slate-800/50' : 'bg-white/70 border-slate-200 hover:border-blue-300 hover:bg-white shadow-sm')
      } ${isSelected ? 'ring-2 ring-blue-500' : ''} group`}
    >
      {/* Header: Flag, Country, Zone, Status Icon */}
      <div className="flex justify-between items-start mb-3">
        <div className="flex items-center gap-3 min-w-0">
          <div className={`flex-shrink-0 w-8 h-6 rounded flex items-center justify-center border overflow-hidden shadow-sm ${isDark ? 'bg-slate-800 border-white/10' : 'bg-slate-100 border-slate-200'}`}>
            <img 
              src={`https://flagcdn.com/w80/${status.code.toLowerCase()}.png`}
              alt={`${status.country} flag`}
              className="w-full h-full object-cover"
              loading="lazy"
            />
          </div>

          <div className="min-w-0">
            <h3 className={`text-sm font-bold tracking-tight leading-tight truncate pr-2 ${isDark ? 'text-white' : 'text-slate-900'}`}>{status.country}</h3>
            <p className={`text-[10px] font-mono truncate opacity-70 group-hover:opacity-100 transition-opacity ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>{status.zone}</p>
          </div>
        </div>

        {status.isIn2026 ? (
          <CheckCircle2 className="text-emerald-500 w-5 h-5 flex-shrink-0 animate-pulse" />
        ) : (
