import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { TIMEZONES, TARGET_DATE_UTC, TARGET_YEAR, LANGUAGES, TRANSLATIONS, Language } from './constants';
import { TransitionStatus, CelebrationInsight } from './types';
import TimeCard from './components/TimeCard';
import InsightPanel from './components/InsightPanel';
import Fireworks from './components/Fireworks';
import Background from './components/Background';
import Timeline from './components/Timeline';
import { getCelebrationInsight } from './services/geminiService';
import { 
  initAudio, 
  playCelebrationSound, 
  playCountdownBeep, 
  playTick, 
  playRandomEffect 
} from './services/audioService';
import { Globe, Timer, Search, LayoutGrid, List, MapPin, Sparkles, CheckCircle2, Clock, ChevronRight, Languages as LangIcon, Sun, Moon } from 'lucide-react';

const formatFullCountdownParts = (ms: number) => {
  if (ms <= 0) return { days: "00", hours: "00", minutes: "00", seconds: "00" };
  const seconds = Math.floor((ms / 1000) % 60);
  const minutes = Math.floor((ms / (1000 * 60)) % 60);
  const hours = Math.floor((ms / (1000 * 60 * 60)) % 24);
  const days = Math.floor(ms / (1000 * 60 * 60 * 24));

  const pad = (n: number) => n.toString().padStart(2, '0');
  return { 
    days: pad(days), 
    hours: pad(hours), 
    minutes: pad(minutes), 
    seconds: pad(seconds) 
  };
};

const App: React.FC = () => {
  const [now, setNow] = useState(new Date());
  const [simulationTime, setSimulationTime] = useState<number | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [selectedCountry, setSelectedCountry] = useState<string | null>(null);
  const [insight, setInsight] = useState<CelebrationInsight | null>(null);
  const [loadingInsight, setLoadingInsight] = useState(false);
  const [localStatus, setLocalStatus] = useState<TransitionStatus | null>(null);
  const [showFireworks, setShowFireworks] = useState(false);
  const lastAudioSecondRef = useRef<number>(-1);

  // Theme State
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const isDark = theme === 'dark';

  // Language State
  const [language, setLanguage] = useState<Language>('en');
  const t = TRANSLATIONS[language];

  // Derived display time (Real or Simulated)
  const displayTime = useMemo(() => {
    return simulationTime ? new Date(simulationTime) : now;
  }, [now, simulationTime]);

  const isSimulating = simulationTime !== null;

  // Initialize audio context on first user interaction to unlock audio
  useEffect(() => {
    const handleInteraction = () => {
      initAudio();
    };
    window.addEventListener('click', handleInteraction, { once: true });
    window.addEventListener('keydown', handleInteraction, { once: true });
    return () => {
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };
  }, []);

  // Update real-time clock
  useEffect(() => {
    const interval = setInterval(() => {
      setNow(new Date());
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // Calculate statuses for all tracked zones based on displayTime
  const statuses = useMemo(() => {
    return TIMEZONES.map(tz => {
      const formatter = new Intl.DateTimeFormat(language === 'en' ? 'en-US' : language, {
        timeZone: tz.zone,
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });

      const localTimeStr = formatter.format(displayTime);
      const zoneStartUTC = TARGET_DATE_UTC - (tz.offset * 60 * 1000);
      const timeTo2026 = zoneStartUTC - displayTime.getTime();
      const isIn2026 = timeTo2026 <= 0;

      return {
        ...tz,
        isIn2026,
        localTime: localTimeStr,
        timeTo2026,
        offset: tz.offset
      } as TransitionStatus;
    }).sort((a, b) => b.offset - a.offset);
  }, [displayTime, language]);

  // Handle local timezone detection, precise countdown, and audio cues
  useEffect(() => {
    try {
      const userZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
      const formatter = new Intl.DateTimeFormat(language === 'en' ? 'en-US' : language, {
        timeZone: userZone,
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });
      const localTimeStr = formatter.format(displayTime);
      const isIn2026 = displayTime.getFullYear() >= TARGET_YEAR;

      const startOf2026Local = new Date(TARGET_YEAR, 0, 1, 0, 0, 0);
      const timeTo2026 = startOf2026Local.getTime() - displayTime.getTime();
      const userOffset = -new Date().getTimezoneOffset();

      // --- AUDIO CUES (Only when NOT simulating to avoid glitchy sound scrubbing) ---
      if (!isSimulating && timeTo2026 > 0 && timeTo2026 <= 60000) {
        // Use ceil so 9.5s remaining counts as "10"
        const currentSecond = Math.ceil(timeTo2026 / 1000);

        if (currentSecond !== lastAudioSecondRef.current) {
             if (currentSecond <= 10) {
                 // Final 10 seconds: Countdown Beep
                 playCountdownBeep();
             } else {
                 // Final Minute (60s to 11s): Subtle Tick
                 playTick();
             }
             lastAudioSecondRef.current = currentSecond;
        }
      }

      setLocalStatus({
        zone: userZone,
        country: 'Local Horizon',
        code: 'UN', 
        isIn2026,
        localTime: localTimeStr,
        timeTo2026,
        offset: userOffset
      });
    } catch (e) {
      console.warn("Could not determine local timezone");
    }
  }, [displayTime, language, isSimulating]);

  // Trigger fireworks and celebration sound
  useEffect(() => {
    // Only auto-trigger sound in live mode, but show visuals in simulation
    if (localStatus?.isIn2026) {
      if (!showFireworks) {
        setShowFireworks(true);
        if (!isSimulating) {
           playCelebrationSound();
        }
        const timer = setTimeout(() => {
          setShowFireworks(false);
        }, 20000);
        return () => clearTimeout(timer);
      }
    } else {
      setShowFireworks(false);
    }
  }, [localStatus?.isIn2026, isSimulating]);

  // Random Atmospheric Sounds during Fireworks (Only Live)
  useEffect(() => {
    if (showFireworks && !isSimulating) {
        const interval = setInterval(() => {
            // 40% chance every 800ms to play a random ambient effect
            if (Math.random() > 0.6) {
                playRandomEffect();
            }
        }, 800);
        return () => clearInterval(interval);
    }
  }, [showFireworks, isSimulating]);

  const handleCountryClick = useCallback(async (country: string) => {
    setSelectedCountry(country);
    setLoadingInsight(true);
    const selectedLangLabel = LANGUAGES.find(l => l.code === language)?.label || 'English';
    const result = await getCelebrationInsight(country, selectedLangLabel);
    setInsight(result);
    setLoadingInsight(false);
  }, [language]);

  const filteredStatuses = useMemo(() => {
    return statuses.filter(s => 
      s.country.toLowerCase().includes(searchTerm.toLowerCase()) ||
      s.zone.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [statuses, searchTerm]);

  const arrivedCountries = useMemo(() => filteredStatuses.filter(s => s.isIn2026), [filteredStatuses]);
  const upcomingCountries = useMemo(() => filteredStatuses.filter(s => !s.isIn2026), [filteredStatuses]);

  const stats = useMemo(() => {
    const in2026 = statuses.filter(s => s.isIn2026).length;
    return {
      in2026,
      remaining: statuses.length - in2026,
      next: statuses.find(s => !s.isIn2026)
    };
  }, [statuses]);

  // Breakdown for Hero Animation
  const countdownParts = localStatus 
    ? formatFullCountdownParts(localStatus.timeTo2026) 
    : { days: "00", hours: "00", minutes: "00", seconds: "00" };

  const handleTimeChange = (time: number) => {
    setSimulationTime(time);
  };

  const toggleSimulation = () => {
    if (isSimulating) {
      setSimulationTime(null);
    } else {
      setSimulationTime(now.getTime());
    }
  };

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  return (
    <div className={`min-h-screen selection:bg-blue-500/30 relative transition-colors duration-1000 ${isDark ? 'text-slate-100' : 'text-slate-800'} ${isSimulating ? (isDark ? 'bg-amber-950/20' : 'bg-amber-50') : ''}`}>
      <Background theme={theme} />
      {showFireworks && <Fireworks />}

      {/* Simulation Overlay Badge */}
      {isSimulating && (
        <div className="fixed top-0 left-0 w-full h-1 bg-amber-500 z-50 animate-pulse shadow-[0_0_15px_rgba(245,158,11,0.5)]"></div>
      )}

      <header className={`sticky top-0 z-40 backdrop-blur-md border-b transition-colors duration-500 ${isSimulating ? (isDark ? 'bg-amber-950/40 border-amber-500/20' : 'bg-amber-100/80 border-amber-200') : (isDark ? 'bg-black/30 border-white/5' : 'bg-white/70 border-slate-200')}`}>
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 transition-all ${isSimulating ? 'bg-gradient-to-br from-amber-600 to-orange-700 ring-amber-500/30' : 'bg-gradient-to-br from-blue-600 to-indigo-700 shadow-blue-900/20 ring-white/10'}`}>
              <Globe className="text-white" size={24} />
            </div>
            <div>
              <h1 className={`text-xl font-black tracking-tight bg-clip-text text-transparent ${isDark ? 'bg-gradient-to-r from-white to-slate-400' : 'bg-gradient-to-r from-slate-900 to-slate-600'}`}>
                {t.appTitle}
              </h1>
            </div>
          </div>

          <div className="flex items-center gap-3 md:gap-6">
            <div className={`hidden md:flex items-center gap-6 text-sm font-medium ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>
                <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full border backdrop-blur-sm transition-colors ${isSimulating ? (isDark ? 'bg-amber-500/10 border-amber-500/20' : 'bg-amber-100 border-amber-200') : (isDark ? 'bg-white/5 border-white/5' : 'bg-slate-100 border-slate-200')}`}>
                  <div className={`w-2 h-2 rounded-full animate-pulse ${isSimulating ? 'bg-amber-500' : 'bg-emerald-500'}`}></div>
                  <span className={isSimulating ? (isDark ? 'text-amber-200' : 'text-amber-700') : ''}>{isSimulating ? t.simulationMode : t.liveUpdates}</span>
                </div>
                {!isSimulating && (
                  <div className="flex items-center gap-2">
                   <span className={isDark ? 'text-white' : 'text-slate-900'}>{stats.in2026}</span> {t.countriesIn2026}
                  </div>
                )}
            </div>

            {/* Theme Toggle */}
            <button 
                onClick={toggleTheme}
                className={`p-2 rounded-lg transition-colors ${isDark ? 'hover:bg-white/10 text-slate-400 hover:text-white' : 'hover:bg-slate-200 text-slate-500 hover:text-slate-900'}`}
                aria-label="Toggle theme"
            >
                {isDark ? <Sun size={18} /> : <Moon size={18} />}
            </button>

            {/* Language Selector */}
            <div className="relative group">
                <div className={`flex items-center gap-2 cursor-pointer p-2 rounded-lg transition-colors ${isDark ? 'hover:bg-white/10' : 'hover:bg-slate-200'}`}>
                    <LangIcon size={18} className={isDark ? 'text-slate-400' : 'text-slate-500'} />
                    <select 
                        value={language}
