            ></div>

            {/* Event Markers */}
            {markers.map((marker) => (
              <div 
                key={marker.time}
                className={`absolute w-3 h-3 -ml-1.5 rounded-full border-2 transition-all duration-300 transform cursor-help z-10 ${
                  currentTime >= marker.time 
