        </div>

        <div className={`flex justify-between mt-2 text-[10px] font-mono uppercase tracking-widest ${isDark ? 'text-slate-500' : 'text-slate-400'}`}>
            <span>Dec 31 10:00 UTC</span>
            <span>Jan 01 12:00 UTC</span>
        </div>
      </div>
    </div>
  );
};

