      const formatter = new Intl.DateTimeFormat(language === 'en' ? 'en-US' : language, {
        timeZone: tz.zone,
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
