import React, { useEffect, useRef } from 'react';
import { getAnalyser } from '../services/audioService';

interface BackgroundProps {
  theme: 'dark' | 'light';
}

const Background: React.FC<BackgroundProps> = ({ theme }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = window.innerWidth;
    let height = window.innerHeight;

    const resize = () => {
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = width;
      canvas.height = height;
    };

    window.addEventListener('resize', resize);
    resize();

    const isDark = theme === 'dark';

    // --- Particle Systems ---

    // 1. Stars (High Frequencies)
    class Star {
      x: number;
      y: number;
      size: number;
      baseSize: number;
      baseAlpha: number;
      currentAlpha: number;
      velocity: number;
      color: string;

      constructor() {
        this.x = Math.random() * width;
        this.y = Math.random() * height;
        this.baseSize = Math.random() * 1.5 + 0.5;
        this.size = this.baseSize;
        this.baseAlpha = Math.random() * 0.3 + 0.1;
        this.currentAlpha = this.baseAlpha;
        this.velocity = Math.random() * 0.05 + 0.02;
        // Darker, slate/blue tone for light mode stars so they are visible
        this.color = isDark ? '255, 255, 255' : '71, 85, 105'; 
      }

      update(energy: number) {
        // High frequency reaction: Sparkle (Alpha) and slight Size increase
        this.y -= this.velocity;
        if (this.y < 0) this.y = height;

        const normalizedEnergy = Math.max(0, (energy - 20) / 255); // Threshold noise

        if (normalizedEnergy > 0) {
            this.currentAlpha = Math.min(1, this.baseAlpha + (normalizedEnergy * 1.5));
            this.size = this.baseSize + (normalizedEnergy * 1.5);
        } else {
            // Decay
            this.currentAlpha += (this.baseAlpha - this.currentAlpha) * 0.1;
            this.size += (this.baseSize - this.size) * 0.1;
        }
      }

      draw() {
        ctx!.fillStyle = `rgba(${this.color}, ${this.currentAlpha})`;
        ctx!.beginPath();
        ctx!.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx!.fill();
      }
    }

    // 2. Confetti (Mid Frequencies)
    class Confetti {
      x: number;
      y: number;
      size: number;
      color: string;
      rotation: number;
      rotationSpeed: number;
      driftX: number;
      driftY: number;

      constructor() {
        this.x = Math.random() * width;
        this.y = Math.random() * height;
        this.size = Math.random() * 4 + 2;
        const darkColors = ['#fcd34d', '#e879f9', '#818cf8']; // Gold, Pink, Indigo
        // More saturated/darker pastel variants for light mode visibility
        const lightColors = ['#d97706', '#c026d3', '#4f46e5', '#0ea5e9']; 
        const colors = isDark ? darkColors : lightColors;
        this.color = colors[Math.floor(Math.random() * colors.length)];
        this.rotation = Math.random() * Math.PI * 2;
        this.rotationSpeed = (Math.random() - 0.5) * 0.02;
        this.driftX = (Math.random() - 0.5) * 0.5;
        this.driftY = Math.random() * 0.5 + 0.2;
      }

      update(energy: number) {
        // Mid frequency reaction: Movement speed and Rotation
        const normalizedEnergy = Math.max(0, (energy - 30) / 255);

        const speedMultiplier = 1 + (normalizedEnergy * 3);

        this.y += this.driftY * speedMultiplier;
        this.x += this.driftX * speedMultiplier;
        this.rotation += this.rotationSpeed * speedMultiplier;

        if (this.y > height) this.y = -10;
        if (this.x > width) this.x = 0;
        if (this.x < 0) this.x = width;
      }

      draw(energy: number) {
        // Opacity reacts slightly
        const normalizedEnergy = Math.max(0, energy / 255);
        const alpha = isDark ? 0.4 + (normalizedEnergy * 0.4) : 0.6 + (normalizedEnergy * 0.3);

        ctx!.save();
        ctx!.translate(this.x, this.y);
        ctx!.rotate(this.rotation);
        ctx!.fillStyle = this.color;
        ctx!.globalAlpha = alpha;
        ctx!.fillRect(-this.size/2, -this.size/2, this.size, this.size);
        ctx!.restore();
      }
    }

    const stars: Star[] = Array.from({ length: 150 }, () => new Star());
    const confetti: Confetti[] = Array.from({ length: 50 }, () => new Confetti());

    let animationId: number;

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      let bassEnergy = 0;
      let midEnergy = 0;
      let highEnergy = 0;

      const analyser = getAnalyser();
      if (analyser) {
        const bufferLength = analyser.frequencyBinCount;
        const dataArray = new Uint8Array(bufferLength);
        analyser.getByteFrequencyData(dataArray);

        // Simple frequency banding
        const bassEnd = Math.floor(bufferLength * 0.1); // ~0-10% (Low Bass)
        const midEnd = Math.floor(bufferLength * 0.5);  // ~10-50% (Mids)

        let bSum = 0, mSum = 0, hSum = 0;
        let bCount = 0, mCount = 0, hCount = 0;

        for (let i = 0; i < bufferLength; i++) {
            const val = dataArray[i];
            if (i < bassEnd) { bSum += val; bCount++; }
            else if (i < midEnd) { mSum += val; mCount++; }
            else { hSum += val; hCount++; }
        }

        bassEnergy = bCount > 0 ? bSum / bCount : 0;
        midEnergy = mCount > 0 ? mSum / mCount : 0;
        highEnergy = hCount > 0 ? hSum / hCount : 0;
      }

      // --- Draw Bass Pulse (Background Layer) ---
      if (bassEnergy > 0) {
        const normalizedBass = bassEnergy / 255;
        // Draw a large soft glow in the bottom center
        const gradient = ctx.createRadialGradient(
            width / 2, height, 0,
            width / 2, height, width * 0.8
        );
        // Golden/Warm bass glow
        const alpha = normalizedBass * 0.3; 
        if (isDark) {
            gradient.addColorStop(0, `rgba(217, 119, 6, ${alpha})`); // Amber-600
            gradient.addColorStop(0.5, `rgba(88, 28, 135, ${alpha * 0.5})`); // Purple-900
            gradient.addColorStop(1, 'rgba(0,0,0,0)');
        } else {
             // Subtle violet/blue pulse for light mode
            gradient.addColorStop(0, `rgba(167, 139, 250, ${alpha * 0.8})`); // Violet-400
            gradient.addColorStop(0.5, `rgba(56, 189, 248, ${alpha * 0.4})`); // Sky-400
            gradient.addColorStop(1, 'rgba(255,255,255,0)');
        }

        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, width, height);
      }

      // --- Draw Confetti (Mids) ---
      confetti.forEach(c => {
        c.update(midEnergy);
        c.draw(midEnergy);
      });

      // --- Draw Stars (Highs) ---
      stars.forEach(s => {
        s.update(highEnergy);
        s.draw();
      });

      animationId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(animationId);
    };
  }, [theme]); // Re-run when theme changes

  const isDark = theme === 'dark';

  return (
    <div className={`fixed inset-0 z-[-1] overflow-hidden pointer-events-none transition-colors duration-1000 ${isDark ? 'bg-[#050505]' : 'bg-[#f8fafc]'}`}>
      {/* Base: Deep Gradient (Static) - Dark Mode */}
      <div className={`absolute inset-0 bg-[radial-gradient(circle_at_top,_var(--tw-gradient-stops))] from-[#1a103c] via-[#050505] to-black transition-opacity duration-1000 ${isDark ? 'opacity-80' : 'opacity-0'}`}></div>

      {/* Base: Light Gradient (Static) - Light Mode - Enhanced for freshness */}
       <div className={`absolute inset-0 bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-blue-100/60 via-slate-50 to-white transition-opacity duration-1000 ${isDark ? 'opacity-0' : 'opacity-100'}`}></div>
       <div className={`absolute inset-0 bg-[radial-gradient(ellipse_at_bottom_left,_var(--tw-gradient-stops))] from-indigo-100/40 via-transparent to-transparent transition-opacity duration-1000 ${isDark ? 'opacity-0' : 'opacity-100'}`}></div>

      {/* LIQUID BLOBS - Adjusted for Light Mode to be soft pastels */}
      <div className={`absolute top-[10%] left-[20%] w-[40rem] h-[40rem] rounded-full mix-blend-multiply filter blur-[80px] animate-drift transition-colors duration-1000 ${isDark ? 'bg-blue-600/40 opacity-40' : 'bg-blue-200/60 opacity-60'}`}></div>
      <div className={`absolute top-[20%] right-[10%] w-[35rem] h-[35rem] rounded-full mix-blend-multiply filter blur-[80px] animate-drift-delayed transition-colors duration-1000 ${isDark ? 'bg-purple-600/40 opacity-40' : 'bg-fuchsia-200/60 opacity-60'}`}></div>
      <div className={`absolute bottom-[10%] left-[30%] w-[45rem] h-[45rem] rounded-full mix-blend-multiply filter blur-[80px] animate-drift transition-colors duration-1000 ${isDark ? 'bg-indigo-600/40 opacity-40' : 'bg-indigo-200/60 opacity-60'}`} style={{ animationDelay: '5s' }}></div>

      {/* Canvas Layer for Audio-Reactive Elements */}
      <canvas ref={canvasRef} className={`absolute inset-0 w-full h-full ${isDark ? 'mix-blend-screen' : 'mix-blend-multiply opacity-70'}`} />

      {/* Vignette */}
      <div className={`absolute inset-0 bg-[radial-gradient(transparent_0%,_#000000_100%)] transition-opacity duration-1000 ${isDark ? 'opacity-60' : 'opacity-[0.03]'}`}></div>
    </div>
  );
};

export default Background;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { TIMEZONES, TARGET_DATE_UTC, TARGET_YEAR, LANGUAGES, TRANSLATIONS, Language } from './constants';
import { TransitionStatus, CelebrationInsight } from './types';
import TimeCard from './components/TimeCard';
import InsightPanel from './components/InsightPanel';
import Fireworks from './components/Fireworks';
import Background from './components/Background';
import Timeline from './components/Timeline';
import { getCelebrationInsight } from './services/geminiService';
import { 
  initAudio, 
  playCelebrationSound, 
  playCountdownBeep, 
  playTick, 
  playRandomEffect 
} from './services/audioService';
import { Globe, Timer, Search, LayoutGrid, List, MapPin, Sparkles, CheckCircle2, Clock, ChevronRight, Languages as LangIcon, Sun, Moon } from 'lucide-react';

const formatFullCountdownParts = (ms: number) => {
  if (ms <= 0) return { days: "00", hours: "00", minutes: "00", seconds: "00" };
  const seconds = Math.floor((ms / 1000) % 60);
  const minutes = Math.floor((ms / (1000 * 60)) % 60);
  const hours = Math.floor((ms / (1000 * 60 * 60)) % 24);
  const days = Math.floor(ms / (1000 * 60 * 60 * 24));

  const pad = (n: number) => n.toString().padStart(2, '0');
  return { 
    days: pad(days), 
    hours: pad(hours), 
    minutes: pad(minutes), 
    seconds: pad(seconds) 
  };
};

const App: React.FC = () => {
  const [now, setNow] = useState(new Date());
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [selectedCountry, setSelectedCountry] = useState<string | null>(null);
  const [insight, setInsight] = useState<CelebrationInsight | null>(null);
  const [loadingInsight, setLoadingInsight] = useState(false);
  const [localStatus, setLocalStatus] = useState<TransitionStatus | null>(null);
  const [showFireworks, setShowFireworks] = useState(false);
  const lastAudioSecondRef = useRef<number>(-1);

  // Theme State
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const isDark = theme === 'dark';

  // Language State: Initialize based on device language
  const [language, setLanguage] = useState<Language>(() => {
    try {
      if (typeof navigator === 'undefined') return 'en';
      const browserLang = navigator.language.split('-')[0];
      const isSupported = LANGUAGES.some(l => l.code === browserLang);
      return isSupported ? (browserLang as Language) : 'en';
    } catch {
      return 'en';
    }
  });

  const t = TRANSLATIONS[language];

  // Initialize audio context on first user interaction to unlock audio
  useEffect(() => {
    const handleInteraction = () => {
      initAudio();
    };
    window.addEventListener('click', handleInteraction, { once: true });
    window.addEventListener('keydown', handleInteraction, { once: true });
    return () => {
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('keydown', handleInteraction);
    };
  }, []);

  // Update real-time clock
  useEffect(() => {
    const interval = setInterval(() => {
      setNow(new Date());
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // Calculate statuses for all tracked zones based on now
  const statuses = useMemo(() => {
    return TIMEZONES.map(tz => {
      const formatter = new Intl.DateTimeFormat(language === 'en' ? 'en-US' : language, {
        timeZone: tz.zone,
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });

      const localTimeStr = formatter.format(now);
      const zoneStartUTC = TARGET_DATE_UTC - (tz.offset * 60 * 1000);
      const timeTo2026 = zoneStartUTC - now.getTime();
      const isIn2026 = timeTo2026 <= 0;

      return {
        ...tz,
        isIn2026,
        localTime: localTimeStr,
        timeTo2026,
        offset: tz.offset
      } as TransitionStatus;
    }).sort((a, b) => b.offset - a.offset);
  }, [now, language]);

  // Handle local timezone detection, precise countdown, and audio cues
  useEffect(() => {
    try {
      const userZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
      const formatter = new Intl.DateTimeFormat(language === 'en' ? 'en-US' : language, {
        timeZone: userZone,
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });
      const localTimeStr = formatter.format(now);
      const isIn2026 = now.getFullYear() >= TARGET_YEAR;

      const startOf2026Local = new Date(TARGET_YEAR, 0, 1, 0, 0, 0);
      const timeTo2026 = startOf2026Local.getTime() - now.getTime();
      const userOffset = -new Date().getTimezoneOffset();

      // --- AUDIO CUES ---
      if (timeTo2026 > 0 && timeTo2026 <= 60000) {
        // Use ceil so 9.5s remaining counts as "10"
        const currentSecond = Math.ceil(timeTo2026 / 1000);

        if (currentSecond !== lastAudioSecondRef.current) {
             if (currentSecond <= 10) {
                 // Final 10 seconds: Countdown Beep
                 playCountdownBeep();
             } else {
                 // Final Minute (60s to 11s): Subtle Tick
                 playTick();
             }
             lastAudioSecondRef.current = currentSecond;
        }
      }

      setLocalStatus({
        zone: userZone,
        country: 'Local Horizon',
        code: 'UN', 
        isIn2026,
        localTime: localTimeStr,
        timeTo2026,
        offset: userOffset
      });
    } catch (e) {
      console.warn("Could not determine local timezone");
    }
  }, [now, language]);

  // Trigger fireworks and celebration sound
  useEffect(() => {
    if (localStatus?.isIn2026) {
      if (!showFireworks) {
        setShowFireworks(true);
        playCelebrationSound();
        const timer = setTimeout(() => {
          setShowFireworks(false);
        }, 20000);
        return () => clearTimeout(timer);
      }
    } else {
      setShowFireworks(false);
    }
  }, [localStatus?.isIn2026]);

  // Random Atmospheric Sounds during Fireworks
  useEffect(() => {
    if (showFireworks) {
        const interval = setInterval(() => {
            // 40% chance every 800ms to play a random ambient effect
            if (Math.random() > 0.6) {
                playRandomEffect();
            }
        }, 800);
        return () => clearInterval(interval);
    }
  }, [showFireworks]);

  const handleCountryClick = useCallback(async (country: string) => {
    setSelectedCountry(country);
    setLoadingInsight(true);
    const selectedLangLabel = LANGUAGES.find(l => l.code === language)?.label || 'English';
    const result = await getCelebrationInsight(country, selectedLangLabel);
    setInsight(result);
    setLoadingInsight(false);
  }, [language]);

  const filteredStatuses = useMemo(() => {
    return statuses.filter(s => 
      s.country.toLowerCase().includes(searchTerm.toLowerCase()) ||
      s.zone.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [statuses, searchTerm]);

  const arrivedCountries = useMemo(() => filteredStatuses.filter(s => s.isIn2026), [filteredStatuses]);
  const upcomingCountries = useMemo(() => filteredStatuses.filter(s => !s.isIn2026), [filteredStatuses]);

  const stats = useMemo(() => {
    const in2026 = statuses.filter(s => s.isIn2026).length;
    return {
      in2026,
      remaining: statuses.length - in2026,
      next: statuses.find(s => !s.isIn2026)
    };
  }, [statuses]);

  // Breakdown for Hero Animation
  const countdownParts = localStatus 
    ? formatFullCountdownParts(localStatus.timeTo2026) 
    : { days: "00", hours: "00", minutes: "00", seconds: "00" };

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

