    try {
      if (typeof navigator === 'undefined') return 'en';
      const browserLang = navigator.language.split('-')[0];
      const isSupported = LANGUAGES.some(l => l.code === browserLang);
      return isSupported ? (browserLang as Language) : 'en';
    } catch {
      return 'en';
    }
  });

