                               <div className={`flex flex-col items-center p-3 sm:p-4 rounded-xl border backdrop-blur-xl min-w-[80px] sm:min-w-[100px] shadow-lg relative overflow-hidden ${isDark ? 'bg-gradient-to-b from-slate-900/40 to-amber-900/20 border-amber-500/20 shadow-amber-900/10' : 'bg-white border-amber-200 shadow-amber-100/50'}`}>
                                   <div className="absolute inset-0 bg-amber-500/5"></div>
                                   <span key={countdownParts.seconds} className="text-5xl sm:text-6xl md:text-7xl font-mono font-black text-gradient-gold tracking-tighter animate-slide-up block relative z-10">
                                       {countdownParts.seconds}
                                   </span>
                                   <span className="text-[10px] text-amber-500/80 font-bold uppercase tracking-widest mt-1 relative z-10">{t.sec}</span>
                               </div>
                           </div>
                        )}
                    </div>

                    {!localStatus.isIn2026 && (
                      <div className={`mt-4 pt-4 border-t flex items-center gap-2 ${isDark ? 'border-white/5' : 'border-slate-200'}`}>
                        <Clock size={14} className="text-slate-500" />
                        <span key={localStatus.localTime} className={`text-xs font-mono animate-slide-up ${isDark ? 'text-slate-300' : 'text-slate-600'}`}>{localStatus.localTime}</span>
                      </div>
                    )}
                  </div>
                )}

                {stats.next && (
                  <div className={`backdrop-blur-2xl p-6 rounded-2xl border shadow-xl transition-all relative overflow-hidden group/next cursor-pointer ${isDark ? 'bg-blue-600/10 border-blue-500/10 hover:bg-blue-600/20' : 'bg-white border-blue-100 hover:border-blue-300 shadow-sm'}`} onClick={() => handleCountryClick(stats.next!.country)}>
                    {/* Decorative glow */}
                    <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/10 blur-[50px] rounded-full pointer-events-none group-hover/next:bg-blue-500/20 transition-colors"></div>

                    <div className="relative z-10">
                      <div className="flex justify-between items-start mb-4">
                        <p className="text-xs text-blue-500 uppercase tracking-widest font-bold flex items-center gap-2">
                          <Timer size={14} /> {t.nextArrival}
                        </p>
                        <div className={`p-1 rounded-full transition-colors backdrop-blur-md ${isDark ? 'bg-white/5 hover:bg-white/10' : 'bg-slate-50 hover:bg-slate-100 border border-slate-200'}`}>
                           <ChevronRight size={14} className="text-blue-400" />
                        </div>
                      </div>

                      <div className="flex items-center gap-4 mb-5">
                        <div className={`w-14 h-10 rounded-md overflow-hidden shadow-lg border flex-shrink-0 relative ${isDark ? 'border-white/10' : 'border-slate-200 bg-white'}`}>
                           <img 
                              src={`https://flagcdn.com/w160/${stats.next.code.toLowerCase()}.png`}
                              alt={stats.next.country}
                              className="w-full h-full object-cover"
                           />
                           <div className="absolute inset-0 ring-1 ring-inset ring-black/10 rounded-md"></div>
                        </div>
                        <div className="min-w-0">
                           <p className={`text-2xl font-black truncate leading-none mb-1 ${isDark ? 'text-white' : 'text-slate-900'}`}>{stats.next.country}</p>
                           <p className={`text-xs truncate font-medium ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>{stats.next.zone}</p>
                        </div>
                      </div>

                      <div className={`flex items-end gap-2 font-mono mb-4 ${isDark ? 'text-blue-200' : 'text-blue-600'}`}>
                         {(() => {
                           const parts = formatFullCountdownParts(stats.next.timeTo2026);
                           const displayTime = parts.days !== "00" 
                              ? `${parts.days}${t.dayShort} ${parts.hours}h ${parts.minutes}m` 
                              : `${parts.hours}:${parts.minutes}:${parts.seconds}`;

                           return (
                             <span className={`text-3xl font-bold tabular-nums tracking-tight animate-tick ${isDark ? 'text-white' : 'text-slate-900'}`}>
                               {displayTime}
                             </span>
                           );
                         })()}
                         <span className="mb-1.5 text-xs font-bold uppercase tracking-wider opacity-60">{t.remaining}</span>
                      </div>

                      <div className="mt-auto">
                        <div className={`h-1.5 w-full rounded-full overflow-hidden border ${isDark ? 'bg-slate-900/50 border-white/5' : 'bg-slate-100 border-slate-200'}`}>
                           <div className="h-full bg-gradient-to-r from-blue-600 to-indigo-400 animate-pulse-slow" style={{ width: '65%' }}></div>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>

            {/* Subtle glow effects behind hero */}
            <div className={`absolute top-0 right-0 w-[500px] h-[500px] blur-[120px] rounded-full pointer-events-none ${isDark ? 'bg-blue-600/10' : 'bg-blue-200/20'}`}></div>
            <div className={`absolute bottom-0 left-0 w-[400px] h-[400px] blur-[100px] rounded-full pointer-events-none ${isDark ? 'bg-indigo-600/10' : 'bg-indigo-200/20'}`}></div>
          </div>

          {/* LIQUID GLASS STATUS PANEL */}
          <div className={`backdrop-blur-xl rounded-3xl p-6 border flex flex-col justify-between shadow-xl ${isDark ? 'bg-slate-900/30 border-white/10' : 'bg-white border-slate-200 shadow-[0_8px_30px_rgba(0,0,0,0.05)]'}`}>
            <div>
              <h3 className={`text-lg font-bold mb-4 ${isDark ? 'text-white' : 'text-slate-900'}`}>{t.globalStatus}</h3>
              <div className="space-y-4">
                <div className={`flex justify-between items-center p-3 rounded-xl border backdrop-blur-md ${isDark ? 'bg-white/5 border-white/5' : 'bg-white border-slate-200 shadow-sm'}`}>
                  <span className={`text-sm ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>{t.countriesIn2026}</span>
                  <span className="text-xl font-bold text-emerald-500 animate-pop" key={stats.in2026}>{stats.in2026}</span>
                </div>
                <div className={`flex justify-between items-center p-3 rounded-xl border backdrop-blur-md ${isDark ? 'bg-white/5 border-white/5' : 'bg-white border-slate-200 shadow-sm'}`}>
                  <span className={`text-sm ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>{t.remainingCount}</span>
                  <span className="text-xl font-bold text-blue-500 animate-pop" key={stats.remaining}>{stats.remaining}</span>
                </div>
              </div>
            </div>

            <div className="mt-8">
              <p className="text-xs text-slate-500 mb-4 leading-relaxed">
                {t.disclaimer}
              </p>
              <button 
                onClick={() => handleCountryClick(stats.next?.country || 'Kiribati')}
                className={`w-full py-3 font-bold rounded-xl transition-colors flex items-center justify-center gap-2 shadow-lg backdrop-blur-sm ${isDark ? 'bg-white text-black hover:bg-slate-200 shadow-white/5' : 'bg-slate-900 text-white hover:bg-slate-800 shadow-slate-900/20'}`}
              >
                {t.learnTraditions}
              </button>
            </div>
          </div>
        </div>

        {/* TIMELINE COMPONENT */}
        <Timeline 
          timezones={TIMEZONES}
          currentTime={now.getTime()}
          statuses={statuses}
          t={t}
          theme={theme}
        />

        {/* Search & View Controls */}
        <div className={`flex flex-col md:flex-row gap-4 mb-8 items-center justify-between sticky top-20 z-30 p-2 -mx-2 rounded-2xl backdrop-blur-xl border transition-colors shadow-lg ${isDark ? 'bg-black/20 border-white/10 shadow-black/10' : 'bg-white/90 border-slate-200 shadow-sm'}`}>
          <div className="relative w-full md:w-96">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
            <input 
              type="text" 
              placeholder={t.searchPlaceholder}
              className={`w-full border rounded-xl py-3 pl-12 pr-4 focus:outline-none focus:ring-2 focus:ring-blue-500/50 transition-all placeholder:text-slate-600 ${isDark ? 'bg-slate-900/60 border-white/10 text-white' : 'bg-white border-slate-200 text-slate-900 focus:bg-white'}`}
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          <div className={`flex items-center gap-2 p-1 rounded-xl border ${isDark ? 'bg-slate-900/60 border-white/10' : 'bg-white border-slate-200'}`}>
            <button 
              onClick={() => setViewMode('grid')}
              className={`p-2 rounded-lg transition-all ${viewMode === 'grid' ? (isDark ? 'bg-white text-black shadow-lg' : 'bg-slate-100 text-slate-900 shadow-inner') : 'text-slate-400 hover:text-slate-500'}`}
            >
              <LayoutGrid size={20} />
            </button>
            <button 
              onClick={() => setViewMode('list')}
              className={`p-2 rounded-lg transition-all ${viewMode === 'list' ? (isDark ? 'bg-white text-black shadow-lg' : 'bg-slate-100 text-slate-900 shadow-inner') : 'text-slate-400 hover:text-slate-500'}`}
            >
              <List size={20} />
            </button>
          </div>
        </div>

        <div className="space-y-12">
          {/* Section: Arrived in 2026 */}
          {arrivedCountries.length > 0 && (
            <section className="animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="flex items-center gap-3 mb-6">
                <div className="p-2 bg-emerald-500/20 rounded-lg text-emerald-500 border border-emerald-500/20 backdrop-blur-sm">
                  <CheckCircle2 size={24} />
                </div>
                <div>
                  <h2 className={`text-2xl font-bold leading-none ${isDark ? 'text-white' : 'text-slate-900'}`}>{t.welcome}</h2>
                  <p className="text-sm text-slate-500 mt-1">{arrivedCountries.length} {t.celebrating}</p>
                </div>
              </div>
              <div className={viewMode === 'grid' 
                ? "grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4" 
                : "space-y-3"
              }>
                {arrivedCountries.map((s) => (
                  <TimeCard 
                    key={s.zone} 
                    status={s} 
                    onClick={handleCountryClick}
                    isSelected={selectedCountry === s.country}
                    isNext={s.country === stats.next?.country}
                    variant={viewMode}
                    t={t}
                    theme={theme}
                  />
                ))}
              </div>
            </section>
          )}

          {/* Section: Counting Down */}
          {upcomingCountries.length > 0 && (
            <section className="animate-in fade-in slide-in-from-bottom-4 duration-700 delay-100">
              <div className="flex items-center gap-3 mb-6">
                 <div className="p-2 bg-blue-500/20 rounded-lg text-blue-500 border border-blue-500/20 backdrop-blur-sm">
                  <Clock size={24} />
                </div>
                <div>
                  <h2 className={`text-2xl font-bold leading-none ${isDark ? 'text-white' : 'text-slate-900'}`}>{t.countdownTitle}</h2>
                  <p className="text-sm text-slate-500 mt-1">{upcomingCountries.length} {t.awaiting}</p>
                </div>
              </div>
              <div className={viewMode === 'grid' 
                ? "grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4" 
                : "space-y-3"
              }>
                {upcomingCountries.map((s) => (
                  <TimeCard 
                    key={s.zone} 
                    status={s} 
                    onClick={handleCountryClick}
                    isSelected={selectedCountry === s.country}
                    isNext={s.country === stats.next?.country}
                    variant={viewMode}
                    t={t}
                    theme={theme}
                  />
                ))}
              </div>
            </section>
          )}

          {filteredStatuses.length === 0 && (
            <div className={`text-center py-20 rounded-3xl border border-dashed ${isDark ? 'bg-slate-900/20 border-white/5' : 'bg-white border-slate-300'}`}>
              <div className={`w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 ${isDark ? 'bg-white/5' : 'bg-slate-100'}`}>
                <Search className="text-slate-500" />
              </div>
              <p className="text-slate-400 font-medium">{t.noResults}</p>
            </div>
          )}
        </div>
      </main>

      <InsightPanel 
        insight={insight} 
        loading={loadingInsight} 
        onClose={() => {
          setInsight(null);
          setSelectedCountry(null);
        }}
        t={t}
        theme={theme}
      />

      <footer className={`mt-20 border-t py-12 px-4 backdrop-blur-xl relative z-10 ${isDark ? 'border-white/5 bg-slate-950/60' : 'border-slate-200 bg-white/70'}`}>
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-8">
          <div className="flex items-center gap-4">
            <div className={`p-3 rounded-2xl ${isDark ? 'bg-white/5' : 'bg-white shadow-sm border border-slate-200'}`}>
              <Globe className="text-slate-400" size={24} />
            </div>
            <div>
              <p className={`font-bold ${isDark ? 'text-white' : 'text-slate-900'}`}>{t.appTitle}</p>
              <p className="text-sm text-slate-500 font-medium">{t.footerText}</p>
            </div>
          </div>
          <div className="text-sm text-slate-600 text-center md:text-right">
            <p>© {new Date().getFullYear()} Global Horizons. {t.poweredBy}</p>
            <p className="mt-1">{t.disclaimer}</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { TransitionStatus } from '../types';
import { Clock, CheckCircle2, Timer, Info } from 'lucide-react';

interface TimeCardProps {
  status: TransitionStatus;
  onClick: (country: string) => void;
  isSelected: boolean;
  isNext?: boolean;
  variant?: 'grid' | 'list';
  t: any;
  theme: 'dark' | 'light';
}

const formatRemainingCompact = (ms: number, dayLabel: string) => {
  if (ms <= 0) return "IN 2026!";
  const seconds = Math.floor((ms / 1000) % 60);
  const minutes = Math.floor((ms / (1000 * 60)) % 60);
  const hours = Math.floor((ms / (1000 * 60 * 60)) % 24);
  const days = Math.floor(ms / (1000 * 60 * 60 * 24));

  const pad = (n: number) => n.toString().padStart(2, '0');

  // Compact format: "3d 04:20:10" or "04:20:10"
  if (days > 0) return `${days}${dayLabel} ${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;
  return `${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;
};

const TimeCard: React.FC<TimeCardProps> = ({ status, onClick, isSelected, isNext, variant = 'grid', t, theme }) => {
  // Extract time and date from the localized string
  // Assumes format roughly contains HH:mm:ss due to app configuration
  const timeMatch = status.localTime.match(/\d{2}:\d{2}:\d{2}/);
  const timePart = timeMatch ? timeMatch[0] : status.localTime.split(',').pop()?.trim() || "";

  let datePart = status.localTime.replace(timePart, '').trim();
  // Clean up separators
  if (datePart.endsWith(',')) datePart = datePart.slice(0, -1).trim();
  if (datePart.startsWith(',')) datePart = datePart.slice(1).trim();

  const isList = variant === 'list';
  const remainingText = formatRemainingCompact(status.timeTo2026, t.dayShort);
  const isDark = theme === 'dark';

  if (isList) {
    return (
      <div 
        onClick={() => onClick(status.country)}
        className={`relative overflow-hidden cursor-pointer transition-all duration-300 p-3 rounded-lg border flex items-center justify-between gap-4 backdrop-blur-xl hover:scale-[1.02] hover:shadow-lg ${
          status.isIn2026 
            ? (isDark ? 'bg-emerald-950/30 border-emerald-500/30 hover:bg-emerald-900/40' : 'bg-emerald-50 border-emerald-200 hover:bg-emerald-100')
            : (isNext 
                ? (isDark ? 'bg-blue-900/30 border-blue-400/60 ring-1 ring-blue-500/50 shadow-[0_0_20px_rgba(59,130,246,0.2)]' : 'bg-white border-blue-300 ring-1 ring-blue-200 shadow-sm')
                : (isDark ? 'bg-slate-900/30 border-white/5 hover:border-white/20 hover:bg-slate-800/40' : 'bg-white border-slate-200 hover:border-blue-300 shadow-sm')
              )
        } ${isSelected ? 'ring-2 ring-blue-500' : ''} group`}
      >
        {/* Left: Identity */}
        <div className="flex items-center gap-3 min-w-0">
          <div className={`flex-shrink-0 w-8 h-6 rounded flex items-center justify-center border overflow-hidden shadow-sm ${isDark ? 'bg-slate-800 border-white/10' : 'bg-white border-slate-200'}`}>
            <img 
              src={`https://flagcdn.com/w80/${status.code.toLowerCase()}.png`}
              alt={`${status.country} flag`}
              className="w-full h-full object-cover transition-transform duration-500 hover:scale-125"
            />
          </div>
          <div className="min-w-0 flex flex-col">
            <div className="flex items-center gap-2">
              <h3 className={`text-sm font-bold tracking-tight leading-tight truncate ${isDark ? 'text-white' : 'text-slate-900'}`}>
                {status.country}
                {isNext && <span className="ml-2 inline-flex items-center rounded-full bg-blue-500/10 px-1.5 py-0.5 text-[10px] font-medium text-blue-500 ring-1 ring-inset ring-blue-500/20">NEXT</span>}
              </h3>
              {status.isIn2026 ? (
                <CheckCircle2 className="text-emerald-500 w-4 h-4 animate-pulse md:hidden" />
              ) : (
                <Timer className={`w-4 h-4 md:hidden ${isNext ? 'text-blue-400' : 'text-blue-500'}`} />
              )}
            </div>
            <div className="flex items-center gap-2">
              <p className={`text-[10px] font-mono truncate opacity-70 ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>{status.zone}</p>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onClick(status.country);
                }}
                className={`md:hidden p-0.5 rounded-full transition-colors ${isDark ? 'text-slate-500 hover:text-blue-400' : 'text-slate-400 hover:text-blue-500'}`}
                aria-label={t.learnTraditions}
              >
                <Info size={12} />
              </button>
            </div>
          </div>
          {/* Desktop Info Button */}
          <button
            onClick={(e) => {
              e.stopPropagation();
              onClick(status.country);
            }}
            className={`hidden md:flex p-1.5 rounded-full transition-colors ${isDark ? 'text-slate-500 hover:bg-white/10 hover:text-blue-400' : 'text-slate-400 hover:bg-slate-100 hover:text-blue-500'}`}
            title={t.learnTraditions}
          >
            <Info size={16} />
          </button>
        </div>

        {/* Right: Data */}
        <div className="flex items-center gap-6 flex-shrink-0">
          {/* Local Time + Date (Hidden on very small screens to save space) */}
          <div className={`hidden sm:flex flex-col items-end justify-center ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>
            <div className="flex items-center gap-2">
                <Clock size={14} />
                <span key={timePart} className="text-xs font-mono font-medium animate-tick tabular-nums">{timePart}</span>
            </div>
            <span className="text-[10px] opacity-70">{datePart}</span>
          </div>

          {/* Countdown/Status */}
          <div className="text-right min-w-[80px]">
             <div className="flex items-center justify-end gap-2 mb-0.5">
                <span className={`text-[10px] font-bold uppercase tracking-wider ${status.isIn2026 ? 'text-emerald-500' : (isDark ? 'text-slate-500' : 'text-slate-500')}`}>
                  {status.isIn2026 ? t.cardLive : t.cardToGo}
                </span>
                {status.isIn2026 ? (
                  <CheckCircle2 className="text-emerald-500 w-3 h-3 hidden md:block" />
                ) : (
                  <Timer className={`w-3 h-3 hidden md:block ${isNext ? 'text-blue-400' : 'text-blue-500'}`} />
                )}
             </div>
             <p key={remainingText} className={`text-sm font-mono font-bold tracking-tight tabular-nums animate-slide-up ${status.isIn2026 ? 'text-emerald-500' : (isNext ? 'text-blue-400' : 'text-blue-500')}`}>
                {remainingText}
             </p>
          </div>
        </div>
      </div>
    );
  }

  // Grid Variant (Default)
  return (
    <div 
      onClick={() => onClick(status.country)}
      className={`relative overflow-hidden cursor-pointer transition-all duration-300 p-4 rounded-xl border backdrop-blur-xl hover:scale-[1.02] hover:shadow-xl ${
        status.isIn2026 
          ? (isDark ? 'bg-emerald-950/30 border-emerald-500/40 hover:bg-emerald-900/40 shadow-[0_4px_20px_rgba(16,185,129,0.1)]' : 'bg-emerald-50 border-emerald-200 hover:bg-emerald-100 shadow-sm') 
          : (isNext
              ? (isDark ? 'bg-blue-900/30 border-blue-400 ring-1 ring-blue-500/50 shadow-[0_0_20px_rgba(59,130,246,0.25)] hover:bg-blue-900/40' : 'bg-white border-blue-300 ring-1 ring-blue-200 shadow-sm hover:bg-slate-50')
              : (isDark ? 'bg-slate-900/30 border-white/5 hover:border-white/20 hover:bg-slate-800/40 shadow-[0_4px_20px_rgba(0,0,0,0.2)]' : 'bg-white border-slate-200 hover:border-blue-300 shadow-sm hover:bg-slate-50')
            )
      } ${isSelected ? 'ring-2 ring-blue-500' : ''} group`}
    >
      {/* Internal Glass Highlight */}
      <div className="absolute inset-0 bg-gradient-to-br from-white/20 via-transparent to-transparent pointer-events-none rounded-xl"></div>

      {/* Header: Flag, Country, Zone, Status Icon */}
      <div className="flex justify-between items-start mb-3 relative z-10">
        <div className="flex items-center gap-3 min-w-0">
          <div className={`flex-shrink-0 w-8 h-6 rounded flex items-center justify-center border overflow-hidden shadow-sm ${isDark ? 'bg-slate-800 border-white/10' : 'bg-white border-slate-200'}`}>
            <img 
              src={`https://flagcdn.com/w80/${status.code.toLowerCase()}.png`}
              alt={`${status.country} flag`}
              className="w-full h-full object-cover transition-transform duration-500 hover:scale-125"
              loading="lazy"
            />
          </div>

          <div className="min-w-0">
            <h3 className={`text-sm font-bold tracking-tight leading-tight truncate pr-2 ${isDark ? 'text-white' : 'text-slate-900'}`}>
              {status.country}
            </h3>
            <p className={`text-[10px] font-mono truncate opacity-70 group-hover:opacity-100 transition-opacity ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>{status.zone}</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
           <button
             onClick={(e) => {
               e.stopPropagation();
               onClick(status.country);
             }}
             className={`p-1 rounded-full transition-colors ${isDark ? 'text-slate-500 hover:bg-white/10 hover:text-blue-400' : 'text-slate-400 hover:bg-slate-100 hover:text-blue-500'}`}
             title={t.learnTraditions}
           >
             <Info size={16} />
           </button>

           {status.isIn2026 ? (
             <CheckCircle2 className="text-emerald-500 w-5 h-5 flex-shrink-0 animate-pulse" />
           ) : (
             <Timer className={`w-5 h-5 flex-shrink-0 ${isNext ? 'text-blue-400 animate-pulse' : 'text-blue-500'}`} />
           )}
        </div>
      </div>

      {isNext && (
          <div className={`absolute top-0 right-0 px-2 py-0.5 text-[8px] font-bold uppercase tracking-wider rounded-bl-lg shadow-sm z-20 ${isDark ? 'bg-blue-500 text-white shadow-blue-500/20' : 'bg-blue-500 text-white shadow-blue-500/20'}`}>
             Next Arrival
          </div>
      )}

      {/* Body: Two-column grid for Time and Countdown */}
      <div className={`grid grid-cols-2 gap-2 pt-3 border-t relative z-10 ${isDark ? 'border-white/5' : 'border-slate-200'}`}>
        <div className="flex flex-col justify-center">
