            this.size += (this.baseSize - this.size) * 0.1;
        }
      }

      draw() {
        const isDark = themeRef.current === 'dark';
        const color = isDark ? '255, 255, 255' : '71, 85, 105'; 

        ctx!.fillStyle = `rgba(${color}, ${this.currentAlpha})`;
        ctx!.beginPath();
        ctx!.arc(this.x, this.y, this.size, 0, Math.PI * 2);
