        );
        const alpha = normalizedBass * 0.3; 
        if (isDark) {
            gradient.addColorStop(0, `rgba(124, 58, 237, ${alpha})`); // Violet pulse
            gradient.addColorStop(0.5, `rgba(29, 78, 216, ${alpha * 0.5})`); // Blue
            gradient.addColorStop(1, 'rgba(0,0,0,0)');
        } else {
